// Static machine-translated drafts. No translation request runs on the published site.
export default Object.freeze({"en":{"copyLanguage":"en","name":"Three Phase Power Calculator","title":"Three Phase Power Calculator Free | UsefulVerse","description":"Calculate single- or three-phase AC active, apparent and reactive power. Free, unlimited and calculated locally in your browser.","intro":"Estimate AC power from line voltage, line current and power factor. Switch between single-phase and balanced three-phase systems, and compare star (wye) or delta phase values.","howQuestion":"How do I calculate three-phase power?","howAnswer":"For a balanced three-phase system, apparent power S = √3 × line voltage × line current, active power P = S × power factor, and reactive-power magnitude Q = S × √(1 − PF²). Single-phase apparent power is V × I. These estimates assume sinusoidal AC and a balanced load for three-phase mode.","privacyQuestion":"Are my electrical values uploaded?","privacyAnswer":"No. The calculation runs in this browser; values you enter are not uploaded or saved by this tool.","fields":{"system":"AC system","singlePhase":"Single phase","threePhase":"Three phase (balanced)","topology":"Three-phase connection","star":"Star / wye","delta":"Delta","lineVoltage":"Line voltage","voltageUnit":"Voltage unit","volts":"Volts (V)","kilovolts":"Kilovolts (kV)","lineCurrent":"Line current","currentUnit":"Current unit","amperes":"Amperes (A)","kiloamperes":"Kiloamperes (kA)","powerFactor":"Power factor (0 to 1)","accuracyNote":"Ideal balanced sinusoidal AC estimate. Power factor is treated as a magnitude; reactive power is shown unsigned. Harmonics, phase imbalance, voltage drops, transient conditions, conductor sizing, protection, safety and electrical-code compliance are not modeled. Use measured equipment data and qualified engineering review for real designs. Values stay in this browser."},"actions":{"calculate":"Calculate AC power","reset":"Reset","copy":"Copy results","example":"Try 400 V, 10 A and PF 0.8","result":"Power estimate"},"messages":{"calculated":"AC power estimate calculated.","checkInputs":"Check voltage, current, power factor and supported units.","activePower":"Active power (P)","apparentPower":"Apparent power (S)","reactivePower":"Reactive power magnitude (Q)","lineVoltage":"Line voltage","lineCurrent":"Line current","phaseVoltage":"Phase voltage","phaseCurrent":"Phase current","powerFactor":"Power factor","formula":"Formula","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"What is the formula for balanced three-phase power?","answer":"Using line-to-line voltage and line current, apparent power is S = √3 × Vline × Iline. Active power is P = S × PF. This assumes a balanced sinusoidal AC system."},{"question":"What is the difference between star and delta?","answer":"For a balanced star (wye) connection, phase voltage is line voltage divided by √3 and phase current equals line current. In delta, phase voltage equals line voltage and phase current is line current divided by √3. The total power for the same line values is the same."},{"question":"Does power factor affect active power?","answer":"Yes. Active power is apparent power multiplied by power factor. Lower power factor means less active power for the same line voltage and current; reactive-power magnitude is estimated from S × √(1 − PF²)."},{"question":"Can I use this for unbalanced loads or electrical safety design?","answer":"No. This is an idealized estimate for single phase or balanced three phase. It does not analyze unbalanced phases, harmonics, wiring, equipment ratings, protection, shock or fire risk, or local electrical codes."}],"localizationStatus":"approved","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"es":{"copyLanguage":"es","name":"Calculadora de potencia trifásica","title":"Calculadora trifásica gratis | UsefulVerse","description":"Calcula potencias activa, aparente y reactiva en corriente alterna monofásica o trifásica. Gratis y en tu navegador.","intro":"Calcule la potencia de CA a partir del voltaje de línea, la corriente de línea y el factor de potencia. \nCambie entre sistemas monofásicos y trifásicos equilibrados y compare valores de fase en estrella (estrella) o delta.","howQuestion":"¿Cómo calculo la potencia trifásica?","howAnswer":"Para un sistema trifásico equilibrado, potencia aparente S = √3 × tensión de línea × corriente de línea, potencia activa P = S × factor de potencia y magnitud de potencia reactiva Q = S × √(1 − PF²). \nLa potencia aparente monofásica es V × I. Estas estimaciones suponen CA sinusoidal y una carga equilibrada para el modo trifásico.","privacyQuestion":"¿Están subidos mis valores eléctricos?","privacyAnswer":"No. El cálculo se ejecuta en este navegador; \nLos valores que ingresa no se cargan ni guardan con esta herramienta.","fields":{"system":"sistema de aire acondicionado","singlePhase":"Monofásico","threePhase":"Trifásico (equilibrado)","topology":"Conexión trifásica","star":"Estrella/estrella","delta":"Delta","lineVoltage":"Tensión de línea","voltageUnit":"Unidad de voltaje","volts":"Voltios (V)","kilovolts":"Kilovoltios (kV)","lineCurrent":"Corriente de línea","currentUnit":"Unidad actual","amperes":"Amperios (A)","kiloamperes":"Kiloamperios (kA)","powerFactor":"Factor de potencia (0 a 1)","accuracyNote":"Estimación de CA sinusoidal equilibrada ideal. \nEl factor de potencia se trata como una magnitud; \nLa potencia reactiva se muestra sin signo. \nNo se modelan los armónicos, el desequilibrio de fases, las caídas de tensión, las condiciones transitorias, el tamaño de los conductores, la protección, la seguridad y el cumplimiento de los códigos eléctricos. \nUtilice datos de equipos medidos y revisiones de ingeniería calificadas para diseños reales. \nLos valores permanecen en este navegador."},"actions":{"calculate":"Calcular potencia CA","reset":"Restablecer","copy":"Copiar resultados","example":"Pruebe 400 V, 10 A y PF 0,8","result":"Estimación de potencia"},"messages":{"calculated":"Estimación de potencia de CA calculada.","checkInputs":"Verificar voltaje, corriente, factor de potencia y unidades soportadas.","activePower":"Potencia activa (P)","apparentPower":"Potencia aparente (S)","reactivePower":"Magnitud de potencia reactiva (Q)","lineVoltage":"Tensión de línea","lineCurrent":"Corriente de línea","phaseVoltage":"Tensión de fase","phaseCurrent":"Corriente de fase","powerFactor":"Factor de potencia","formula":"Fórmula","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"¿Cuál es la fórmula para la potencia trifásica equilibrada?","answer":"Usando voltaje línea a línea y corriente de línea, la potencia aparente es S = √3 × Vlínea × Ilínea. \nLa potencia activa es P = S × PF. \nEsto supone un sistema de CA sinusoidal equilibrado."},{"question":"¿Cuál es la diferencia entre estrella y delta?","answer":"Para una conexión equilibrada en estrella (estrella), el voltaje de fase es el voltaje de línea dividido por √3 y la corriente de fase es igual a la corriente de línea. \nEn delta, el voltaje de fase es igual al voltaje de línea y la corriente de fase es la corriente de línea dividida por √3. \nLa potencia total para los mismos valores de línea es la misma."},{"question":"¿El factor de potencia afecta la potencia activa?","answer":"Sí. \nLa potencia activa es la potencia aparente multiplicada por el factor de potencia. \nUn factor de potencia más bajo significa menos potencia activa para el mismo voltaje y corriente de línea; \nLa magnitud de la potencia reactiva se estima a partir de S × √(1 − PF²)."},{"question":"¿Puedo usar esto para cargas desequilibradas o diseño de seguridad eléctrica?","answer":"No. Esta es una estimación idealizada para monofásico o trifásico equilibrado. \nNo analiza fases desequilibradas, armónicos, cableado, clasificaciones de equipos, protección, riesgo de descarga o incendio, ni códigos eléctricos locales."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"fr":{"copyLanguage":"fr","name":"Calculateur de puissance triphasé","title":"Calculateur de puissance triphasé | UsefulVerse","description":"Calcule la puissance active, apparente et réactive AC monophasée ou triphasée. \nGratuit, illimité et calculé localement dans votre navigateur.","intro":"Estimation de la puissance CA à partir de la tension secteur, du courant secteur et du facteur de puissance. \nBasculez entre les systèmes monophasés et triphasés équilibrés et comparez les valeurs de phase étoile (étoile) ou triangle.","howQuestion":"Comment calculer la puissance triphasée ?","howAnswer":"Pour un système triphasé équilibré, puissance apparente S = √3 × tension de ligne × courant de ligne, puissance active P = S × facteur de puissance et amplitude de puissance réactive Q = S × √(1 − PF²). \nLa puissance apparente monophasée est V × I. Ces estimations supposent un courant alternatif sinusoïdal et une charge équilibrée pour le mode triphasé.","privacyQuestion":"Mes valeurs électriques sont-elles téléchargées ?","privacyAnswer":"Non. Le calcul s'exécute dans ce navigateur ; \nles valeurs que vous saisissez ne sont ni téléchargées ni enregistrées par cet outil.","fields":{"system":"Système CA","singlePhase":"Monophasé","threePhase":"Triphasé (équilibré)","topology":"Raccordement triphasé","star":"Étoile / étoile","delta":"Delta","lineVoltage":"Tension secteur","voltageUnit":"Unité de tension","volts":"Volts (V)","kilovolts":"Kilovolts (kV)","lineCurrent":"Courant de ligne","currentUnit":"Unité actuelle","amperes":"Ampères (A)","kiloamperes":"Kiloampères (kA)","powerFactor":"Facteur de puissance (0 à 1)","accuracyNote":"Estimation CA sinusoïdale équilibrée idéale. \nLe facteur de puissance est traité comme une grandeur ; \nla puissance réactive est indiquée sans signe. \nLes harmoniques, le déséquilibre de phase, les chutes de tension, les conditions transitoires, le dimensionnement des conducteurs, la protection, la sécurité et la conformité aux codes électriques ne sont pas modélisés. \nUtilisez les données mesurées sur les équipements et les examens techniques qualifiés pour des conceptions réelles. \nLes valeurs restent dans ce navigateur."},"actions":{"calculate":"Calculer la puissance CA","reset":"Réinitialiser","copy":"Copier les résultats","example":"Essayez 400 V, 10 A et PF 0,8","result":"Estimation de puissance"},"messages":{"calculated":"Estimation de la puissance CA calculée.","checkInputs":"Vérifiez la tension, le courant, le facteur de puissance et les unités prises en charge.","activePower":"Puissance active (P)","apparentPower":"Puissance apparente (S)","reactivePower":"Ampleur de puissance réactive (Q)","lineVoltage":"Tension secteur","lineCurrent":"Courant de ligne","phaseVoltage":"Tension de phase","phaseCurrent":"Courant de phase","powerFactor":"Facteur de puissance\n\nFormule","formula":"Formula","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"Quelle est la formule pour une alimentation triphasée équilibrée ?","answer":"En utilisant la tension ligne à ligne et le courant de ligne, la puissance apparente est S = √3 × Vline × Iline. \nLa puissance active est P = S × PF. \nCela suppose un système AC sinusoïdal équilibré."},{"question":"Quelle est la différence entre étoile et triangle ?","answer":"Pour une connexion en étoile (étoile) équilibrée, la tension de phase est la tension de ligne divisée par √3 et le courant de phase est égal au courant de ligne. \nEn triangle, la tension de phase est égale à la tension de ligne et le courant de phase est le courant de ligne divisé par √3. \nLa puissance totale pour les mêmes valeurs de ligne est la même."},{"question":"Le facteur de puissance affecte-t-il la puissance active ?","answer":"Oui. \nLa puissance active est la puissance apparente multipliée par le facteur de puissance. \nUn facteur de puissance inférieur signifie moins de puissance active pour la même tension et le même courant de ligne ; \nl'amplitude de la puissance réactive est estimée à partir de S × √ (1 − PF²)."},{"question":"Puis-je l'utiliser pour des charges déséquilibrées ou pour une conception de sécurité électrique ?","answer":"Non. Il s'agit d'une estimation idéalisée pour un monophasé ou un triphasé équilibré. \nIl n'analyse pas les phases déséquilibrées, les harmoniques, le câblage, les caractéristiques nominales des équipements, la protection, les risques de choc ou d'incendie, ni les codes électriques locaux."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"pt":{"copyLanguage":"pt","name":"Calculadora de potência trifásica","title":"Calculadora de potência trifásica | UsefulVerse","description":"Calcule a potência CA ativa, aparente e reativa monofásica ou trifásica. \nGratuito, ilimitado e calculado localmente no seu navegador.","intro":"Estime a potência CA a partir da tensão da linha, da corrente da linha e do fator de potência. \nAlterne entre sistemas monofásicos e trifásicos balanceados e compare os valores das fases estrela (estrela) ou delta.","howQuestion":"Como calculo a potência trifásica?","howAnswer":"Para um sistema trifásico balanceado, potência aparente S = √3 × tensão de linha × corrente de linha, potência ativa P = S × fator de potência e magnitude de potência reativa Q = S × √(1 − PF²). \nA potência aparente monofásica é V × I. Essas estimativas assumem CA senoidal e uma carga balanceada para o modo trifásico.","privacyQuestion":"Meus valores elétricos foram carregados?","privacyAnswer":"Não. O cálculo é executado neste navegador; \nos valores inseridos não são carregados ou salvos por esta ferramenta.","fields":{"system":"sistema CA","singlePhase":"Monofásico","threePhase":"Trifásico (balanceado)","topology":"Conexão trifásica","star":"Estrela/estrela","delta":"Delta","lineVoltage":"Tensão de linha","voltageUnit":"Unidade de tensão","volts":"Volts (V)","kilovolts":"Quilovolts (kV)","lineCurrent":"Corrente de linha","currentUnit":"Unidade atual","amperes":"Amperes (A)","kiloamperes":"Quiloampères (kA)","powerFactor":"Fator de potência (0 a 1)","accuracyNote":"Estimativa de CA senoidal balanceada ideal. \nO fator de potência é tratado como uma magnitude; \na potência reativa é mostrada sem sinal. \nHarmônicos, desequilíbrio de fase, quedas de tensão, condições transitórias, dimensionamento de condutores, proteção, segurança e conformidade com códigos elétricos não são modelados. \nUse dados de equipamentos medidos e revisão de engenharia qualificada para projetos reais. \nOs valores permanecem neste navegador."},"actions":{"calculate":"Calcular energia CA","reset":"Redefinir","copy":"Copiar resultados","example":"Experimente 400 V, 10 A e PF 0,8","result":"Estimativa de energia"},"messages":{"calculated":"Estimativa de energia CA calculada.","checkInputs":"Verifique tensão, corrente, fator de potência e unidades suportadas.","activePower":"Potência ativa (P)","apparentPower":"Potência aparente (S)","reactivePower":"Magnitude de potência reativa (Q)","lineVoltage":"Tensão de linha","lineCurrent":"Corrente de linha","phaseVoltage":"Tensão de fase","phaseCurrent":"Corrente de fase","powerFactor":"Fator de potência","formula":"Fórmula","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"Qual é a fórmula para alimentação trifásica balanceada?","answer":"Usando tensão linha a linha e corrente de linha, a potência aparente é S = √3 × Vline × Iline. \nA potência ativa é P = S × PF. \nIsso pressupõe um sistema CA senoidal balanceado."},{"question":"Qual é a diferença entre estrela e delta?","answer":"Para uma conexão estrela balanceada (estrela), a tensão de fase é a tensão de linha dividida por √3 e a corrente de fase é igual à corrente de linha. \nEm delta, a tensão de fase é igual à tensão de linha e a corrente de fase é a corrente de linha dividida por √3. \nA potência total para os mesmos valores de linha é a mesma."},{"question":"O fator de potência afeta a potência ativa?","answer":"Sim. \nA potência ativa é a potência aparente multiplicada pelo fator de potência. \nFator de potência mais baixo significa menos potência ativa para a mesma tensão e corrente de linha; \na magnitude da potência reativa é estimada a partir de S × √(1 − PF²)."},{"question":"Posso usar isso para cargas desequilibradas ou projetos de segurança elétrica?","answer":"Não. Esta é uma estimativa idealizada para monofásico ou trifásico balanceado. \nEle não analisa fases desequilibradas, harmônicos, fiação, classificações de equipamentos, proteção, risco de choque ou incêndio ou códigos elétricos locais."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"de":{"copyLanguage":"de","name":"Dreiphasen-Leistungsrechner","title":"Dreiphasen-Leistungsrechner | UsefulVerse","description":"Berechnen Sie die Wirk-, Schein- und Blindleistung von ein- oder dreiphasigem Wechselstrom. \nKostenlos, unbegrenzt und lokal in Ihrem Browser berechnet.","intro":"Schätzen Sie die Wechselstromleistung anhand der Netzspannung, des Netzstroms und des Leistungsfaktors. \nWechseln Sie zwischen einphasigen und symmetrischen dreiphasigen Systemen und vergleichen Sie Stern- (Stern-) oder Dreieckphasenwerte.","howQuestion":"Wie berechne ich die Dreiphasenleistung?","howAnswer":"Für ein ausgeglichenes Dreiphasensystem ist die Scheinleistung S = √3 × Netzspannung × Netzstrom, die Wirkleistung P = S × Leistungsfaktor und die Größe der Blindleistung Q = S × √(1 − PF²). \nDie einphasige Scheinleistung beträgt V × I. Diese Schätzungen gehen von einem sinusförmigen Wechselstrom und einer ausgeglichenen Last für den Dreiphasenmodus aus.","privacyQuestion":"Werden meine elektrischen Werte hochgeladen?","privacyAnswer":"Nein. Die Berechnung läuft in diesem Browser; \nDie von Ihnen eingegebenen Werte werden von diesem Tool nicht hochgeladen oder gespeichert.","fields":{"system":"Wechselstromsystem","singlePhase":"Einphasig","threePhase":"Dreiphasig (symmetrisch)","topology":"Dreiphasiger Anschluss","star":"Stern / Stern","delta":"Delta","lineVoltage":"Netzspannung","voltageUnit":"Spannungseinheit","volts":"Volt (V)","kilovolts":"Kilovolt (kV)","lineCurrent":"Netzstrom","currentUnit":"Aktuelle Einheit","amperes":"Ampere (A)","kiloamperes":"Kiloampere (kA)","powerFactor":"Leistungsfaktor (0 bis 1)","accuracyNote":"Ideale ausgeglichene sinusförmige Wechselstromschätzung. \nDer Leistungsfaktor wird als Größe behandelt; \nBlindleistung wird ohne Vorzeichen angezeigt. \nOberschwingungen, Phasenungleichgewicht, Spannungsabfälle, Übergangsbedingungen, Leiterdimensionierung, Schutz, Sicherheit und Einhaltung elektrischer Vorschriften werden nicht modelliert. \nNutzen Sie gemessene Gerätedaten und qualifizierte technische Prüfungen für reale Entwürfe. \nWerte bleiben in diesem Browser."},"actions":{"calculate":"Wechselstromleistung berechnen","reset":"Zurücksetzen","copy":"Ergebnisse kopieren","example":"Versuchen Sie es mit 400 V, 10 A und PF 0,8","result":"Leistungsschätzung"},"messages":{"calculated":"AC-Leistungsschätzung berechnet.","checkInputs":"Überprüfen Sie Spannung, Strom, Leistungsfaktor und unterstützte Einheiten.","activePower":"Wirkleistung (P)","apparentPower":"Scheinleistung (S)","reactivePower":"Blindleistungsbetrag (Q)","lineVoltage":"Netzspannung","lineCurrent":"Netzstrom","phaseVoltage":"Phasenspannung","phaseCurrent":"Phasenstrom","powerFactor":"Leistungsfaktor","formula":"Formel","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"Wie lautet die Formel für eine ausgeglichene dreiphasige Stromversorgung?","answer":"Unter Verwendung der verketteten Spannung und des Leitungsstroms beträgt die Scheinleistung S = √3 × ULeitung × ILeitung. \nDie Wirkleistung beträgt P = S × PF. \nDies setzt ein ausgeglichenes sinusförmiges Wechselstromsystem voraus."},{"question":"Was ist der Unterschied zwischen Stern und Delta?","answer":"Bei einer symmetrischen Sternschaltung (Sternschaltung) ist die Phasenspannung die Netzspannung geteilt durch √3 und der Phasenstrom gleich dem Netzstrom. \nIm Dreieck ist die Phasenspannung gleich der Netzspannung und der Phasenstrom ist der Netzstrom geteilt durch √3. \nDie Gesamtleistung ist bei gleichen Leitungswerten gleich."},{"question":"Beeinflusst der Leistungsfaktor die Wirkleistung?","answer":"Ja. \nWirkleistung ist die Scheinleistung multipliziert mit dem Leistungsfaktor. \nEin niedrigerer Leistungsfaktor bedeutet weniger Wirkleistung bei gleicher Netzspannung und gleichem Strom; \nDie Größe der Blindleistung wird aus S × √(1 − PF²) geschätzt."},{"question":"Kann ich dies für unsymmetrische Lasten oder elektrische Sicherheitskonstruktionen verwenden?","answer":"Nein. Dies ist eine idealisierte Schätzung für einphasige oder ausgeglichene dreiphasige. \nUnsymmetrische Phasen, Oberschwingungen, Verkabelung, Gerätebewertungen, Schutz, Stromschlag- oder Brandgefahr oder örtliche Elektrovorschriften werden nicht analysiert."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"ja":{"copyLanguage":"ja","name":"三相電力計算機","title":"三相電力計算機 | UsefulVerse","description":"単相または三相 AC の有効電力、皮相電力、無効電力を計算します。\n無料、無制限、ブラウザ内でローカルに計算されます。","intro":"線間電圧、線間電流、力率から AC 電力を推定します。\n単相システムと平衡三相システムを切り替え、スター (Y 位相) またはデルタ位相の値を比較します。","howQuestion":"三相電力を計算するにはどうすればよいですか?","howAnswer":"平衡三相システムの場合、皮相電力 S = √3 × 線間電圧 × 線電流、有効電力 P = S × 力率、および無効電力の大きさ Q = S × √(1 − PF²)。\n単相皮相電力は V × I です。これらの推定値は、三相モードの正弦波 AC と平衡負荷を前提としています。","privacyQuestion":"私の電気的値はアップロードされていますか?","privacyAnswer":"いいえ。計算はこのブラウザで実行されます。\n入力した値は、このツールによってアップロードまたは保存されません。","fields":{"system":"ACシステム","singlePhase":"単相","threePhase":"三相（平衡）","topology":"三相結線","star":"スター/ワイ","delta":"デルタ","lineVoltage":"線間電圧","voltageUnit":"電圧単位","volts":"ボルト (V)","kilovolts":"キロボルト (kV)","lineCurrent":"線電流","currentUnit":"現在の単位","amperes":"アンペア (A)","kiloamperes":"キロアンペア (kA)","powerFactor":"力率（0～1）","accuracyNote":"理想的な平衡正弦波 AC 推定値。\n力率は大きさとして扱われます。\n無効電力は符号なしで表示されます。\n高調波、位相不均衡、電圧降下、過渡状態、導体のサイジング、保護、安全性、電気規定への準拠はモデル化されていません。\n実際の設計には、測定された機器データと適格なエンジニアリング レビューを使用します。\n値はこのブラウザ内に残ります。"},"actions":{"calculate":"AC 電力を計算します","reset":"リセット","copy":"結果をコピー","example":"400 V、10 A、PF 0.8 を試してください","result":"電力の見積もり"},"messages":{"calculated":"AC 電力の推定値が計算されました。","checkInputs":"電圧、電流、力率、およびサポートされている単位を確認してください。","activePower":"有効電力(P)","apparentPower":"皮相電力(S)","reactivePower":"無効電力の大きさ (Q)","lineVoltage":"線間電圧","lineCurrent":"線電流","phaseVoltage":"相電圧","phaseCurrent":"相電流","powerFactor":"力率","formula":"式","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"平衡三相電力の計算式は何ですか?","answer":"線間電圧と線電流を使用すると、皮相電力は S = √3 × Vline × Iline となります。\n有効電力は P = S × PF です。\nこれは平衡正弦波 AC システムを想定しています。"},{"question":"スターとデルタの違いは何ですか?","answer":"平衡スター (Y 字) 接続の場合、相電圧は線間電圧を √3 で割った値であり、相電流は線電流と等しくなります。\nデルタでは、相電圧は線間電圧に等しく、相電流は線路電流を√3 で割ったものです。\n同じライン値の合計パワーは同じです。"},{"question":"力率は有効電力に影響しますか?","answer":"はい。\n有効電力は皮相電力に力率を乗じたものです。\n力率が低いということは、同じ線間電圧と電流に対する有効電力が少ないことを意味します。\n無効電力の大きさは S × √(1 − PF²) から推定されます。"},{"question":"不平衡負荷や電気安全設計に使用できますか?","answer":"いいえ。これは、単相または平衡三相の理想的な推定値です。\n不平衡位相、高調波、配線、機器の定格、保護、感電または火災の危険性、または地域の電気規定は分析されません。"}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"ko":{"copyLanguage":"ko","name":"삼상 전력 계산기","title":"삼상 전력 계산기 | UsefulVerse","description":"단상 또는 3상 AC 유효, 피상 및 무효 전력을 계산합니다. \n무료이며 무제한이며 브라우저에서 로컬로 계산됩니다.","intro":"선간 전압, 선전류 및 역률로부터 AC 전력을 추정합니다. \n단상 및 평형 3상 시스템 간을 전환하고 스타(Wye) 또는 델타 위상 값을 비교합니다.","howQuestion":"3상 전력은 어떻게 계산하나요?","howAnswer":"평형 3상 시스템의 경우 피상 전력 S = √3 × 선간 전압 × 선간 전류, 유효 전력 P = S × 역률, 무효 전력 크기 Q = S × √(1 − PF²). \n단상 피상 전력은 V × I입니다. 이 추정치는 3상 모드에 대한 정현파 AC 및 균형 부하를 가정합니다.","privacyQuestion":"전기 값이 업로드됩니까?","privacyAnswer":"아니요. 계산은 이 브라우저에서 실행됩니다. \n입력한 값은 이 도구에 의해 업로드되거나 저장되지 않습니다.","fields":{"system":"AC 시스템","singlePhase":"단상","threePhase":"3상(균형)","topology":"3상 결선","star":"별/와이","delta":"델타","lineVoltage":"라인 전압","voltageUnit":"전압 단위","volts":"볼트(V)","kilovolts":"킬로볼트(kV)","lineCurrent":"라인 전류","currentUnit":"현재 단위","amperes":"암페어(A)","kiloamperes":"킬로암페어(kA)","powerFactor":"역률(0 ~ 1)","accuracyNote":"이상적인 균형 정현파 AC 추정치입니다. \n역률은 크기로 간주됩니다. \n무효 전력은 부호 없이 표시됩니다. \n고조파, 위상 불균형, 전압 강하, 과도 조건, 도체 크기, 보호, 안전 및 전기 규정 준수는 모델링되지 않습니다. \n실제 설계를 위해 측정된 장비 데이터와 검증된 엔지니어링 검토를 사용하십시오. \n값은 이 브라우저에 유지됩니다."},"actions":{"calculate":"AC 전력 계산","reset":"재설정","copy":"결과 복사","example":"400V, 10A 및 PF 0.8을 사용해 보세요.","result":"전력 추정"},"messages":{"calculated":"AC 전력 추정치가 계산되었습니다.","checkInputs":"전압, 전류, 역률 및 지원 단위를 확인하세요.","activePower":"유효전력(P)","apparentPower":"피상전력(S)","reactivePower":"무효전력 크기(Q)","lineVoltage":"라인 전압","lineCurrent":"라인 전류","phaseVoltage":"상전압","phaseCurrent":"위상 전류","powerFactor":"역률","formula":"수식","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"균형 잡힌 3상 전력의 공식은 무엇입니까?","answer":"선간 전압과 선전류를 이용하면 피상전력은 S = √3 × Vline × Iline 입니다. \n유효 전력은 P = S × PF입니다. \n이는 평형 정현파 AC 시스템을 가정합니다."},{"question":"스타와 델타의 차이점은 무엇인가요?","answer":"평형 스타(Wye) 연결의 경우 위상 전압은 라인 전압을 √3으로 나눈 값이고 위상 전류는 라인 전류와 같습니다. \n델타에서 위상 전압은 라인 전압과 동일하고 위상 전류는 라인 전류를 √3으로 나눈 값입니다. \n동일한 라인 값에 대한 총 전력은 동일합니다."},{"question":"역률이 유효전력에 영향을 미치나요?","answer":"네. \n유효 전력은 피상 전력에 역률을 곱한 값입니다. \n역률이 낮다는 것은 동일한 라인 전압 및 전류에 대해 유효 전력이 적다는 것을 의미합니다. \n무효 전력 크기는 S × √(1 − PF²)로 추정됩니다."},{"question":"불균형 부하나 전기 안전 설계에 사용할 수 있나요?","answer":"아니요. 이는 단상 또는 평형 3상에 대한 이상적인 추정치입니다. \n불균형 위상, 고조파, 배선, 장비 등급, 보호, 감전 또는 화재 위험, 현지 전기 규정은 분석하지 않습니다."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"id":{"copyLanguage":"id","name":"Kalkulator Daya Tiga Fasa","title":"Kalkulator Daya Tiga Fasa | UsefulVerse","description":"Hitung daya aktif, semu, dan reaktif AC satu atau tiga fasa. \nGratis, tidak terbatas, dan dihitung secara lokal di browser Anda.","intro":"Perkirakan daya AC dari tegangan saluran, arus saluran, dan faktor daya. \nBeralih antara sistem satu fase dan tiga fase seimbang, dan bandingkan nilai fase bintang (wye) atau delta.","howQuestion":"Bagaimana cara menghitung daya tiga fasa?","howAnswer":"Untuk sistem tiga fasa seimbang, daya semu S = √3 × tegangan saluran × arus saluran, daya aktif P = S × faktor daya, dan besaran daya reaktif Q = S × √(1 − PF²). \nDaya nyata satu fasa adalah V × I. Perkiraan ini mengasumsikan AC sinusoidal dan beban seimbang untuk mode tiga fasa.","privacyQuestion":"Apakah nilai kelistrikan saya sudah terupload?","privacyAnswer":"No. Perhitungan berjalan di browser ini; \nnilai yang Anda masukkan tidak diunggah atau disimpan oleh alat ini.","fields":{"system":"Sistem AC","singlePhase":"Fase tunggal","threePhase":"Tiga fase (seimbang)","topology":"Sambungan tiga fasa","star":"Bintang/Wye","delta":"Delta","lineVoltage":"Tegangan saluran","voltageUnit":"Satuan tegangan","volts":"Volt (V)","kilovolts":"Kilovolt (kV)","lineCurrent":"Arus saluran","currentUnit":"Satuan saat ini","amperes":"Ampere (A)","kiloamperes":"Kiloampere (kA)","powerFactor":"Faktor daya (0 hingga 1)","accuracyNote":"Perkiraan AC sinusoidal seimbang yang ideal. \nFaktor daya diperlakukan sebagai besaran; \ndaya reaktif ditampilkan tanpa tanda tangan. \nHarmonisa, ketidakseimbangan fasa, penurunan tegangan, kondisi transien, ukuran konduktor, proteksi, keselamatan, dan kepatuhan kode kelistrikan tidak dimodelkan. \nGunakan data peralatan terukur dan tinjauan teknik yang memenuhi syarat untuk desain nyata. \nNilai tetap ada di browser ini."},"actions":{"calculate":"Hitung daya AC","reset":"Atur Ulang","copy":"Salin hasil","example":"Coba 400 V, 10 A dan PF 0,8","result":"Perkiraan daya"},"messages":{"calculated":"Perkiraan daya AC dihitung.","checkInputs":"Periksa tegangan, arus, faktor daya dan unit pendukung.","activePower":"Daya aktif (P)","apparentPower":"Daya semu (S)","reactivePower":"Besaran daya reaktif (Q)","lineVoltage":"Tegangan saluran","lineCurrent":"Arus saluran","phaseVoltage":"Tegangan fasa","phaseCurrent":"Arus fasa","powerFactor":"Faktor daya","formula":"Rumus","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"Apa rumus daya tiga fasa seimbang?","answer":"Menggunakan tegangan saluran-ke-saluran dan arus saluran, daya semu adalah S = √3 × Vline × Iline. \nDaya aktifnya adalah P = S × PF. \nIni mengasumsikan sistem AC sinusoidal seimbang."},{"question":"Apa perbedaan bintang dan delta?","answer":"Untuk sambungan bintang seimbang (wye), tegangan fasa adalah tegangan saluran dibagi √3 dan arus fasa sama dengan arus saluran. \nDalam delta, tegangan fasa sama dengan tegangan saluran dan arus fasa adalah arus saluran dibagi √3. \nTotal daya untuk nilai saluran yang sama adalah sama."},{"question":"Apakah faktor daya mempengaruhi daya aktif?","answer":"Ya. \nDaya aktif adalah daya semu dikalikan faktor daya. \nFaktor daya yang lebih rendah berarti lebih sedikit daya aktif untuk tegangan dan arus saluran yang sama; \nbesaran daya reaktif diperkirakan dari S × √(1 − PF²)."},{"question":"Dapatkah saya menggunakan ini untuk beban tidak seimbang atau desain keselamatan listrik?","answer":"Tidak. Ini adalah perkiraan ideal untuk fase tunggal atau tiga fase seimbang. \nIni tidak menganalisis fase tidak seimbang, harmonik, perkabelan, peringkat peralatan, perlindungan, risiko sengatan atau kebakaran, atau kode kelistrikan lokal."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"hi":{"copyLanguage":"hi","name":"तीन-फेज़ पावर कैलकुलेटर","title":"तीन-फेज़ पावर कैलकुलेटर | UsefulVerse","description":"एकल या तीन-चरण एसी सक्रिय, स्पष्ट और प्रतिक्रियाशील शक्ति की गणना करें। \nआपके ब्राउज़र में मुफ़्त, असीमित और स्थानीय रूप से गणना की गई।","intro":"लाइन वोल्टेज, लाइन करंट और पावर फैक्टर से एसी पावर का अनुमान लगाएं। \nएकल-चरण और संतुलित तीन-चरण प्रणालियों के बीच स्विच करें, और स्टार (वाई) या डेल्टा चरण मानों की तुलना करें।","howQuestion":"मैं तीन-चरण शक्ति की गणना कैसे करूं?","howAnswer":"एक संतुलित तीन-चरण प्रणाली के लिए, स्पष्ट शक्ति एस = √3 × लाइन वोल्टेज × लाइन वर्तमान, सक्रिय शक्ति पी = एस × शक्ति कारक, और प्रतिक्रियाशील-शक्ति परिमाण क्यू = एस × √(1 - पीएफ²)। \nएकल-चरण स्पष्ट शक्ति V × I है। ये अनुमान साइनसॉइडल एसी और तीन-चरण मोड के लिए एक संतुलित भार मानते हैं।","privacyQuestion":"क्या मेरे विद्युत मान अपलोड किए गए हैं?","privacyAnswer":"नहीं। गणना इस ब्राउज़र में चलती है; \nआपके द्वारा दर्ज किए गए मान इस टूल द्वारा अपलोड या सहेजे नहीं जाते हैं।","fields":{"system":"एसी सिस्टम","singlePhase":"एकल चरण","threePhase":"तीन चरण (संतुलित)","topology":"तीन-चरण कनेक्शन","star":"स्टार/वाई","delta":"डेल्टा","lineVoltage":"लाइन वोल्टेज","voltageUnit":"वोल्टेज इकाई","volts":"वोल्ट (वी)","kilovolts":"किलोवोल्ट (केवी)","lineCurrent":"लाइन करंट","currentUnit":"वर्तमान इकाई","amperes":"एम्पीयर (ए)","kiloamperes":"किलोएम्पेयर (केए)","powerFactor":"पावर फैक्टर (0 से 1)","accuracyNote":"आदर्श संतुलित साइनसोइडल एसी अनुमान। \nशक्ति कारक को परिमाण के रूप में माना जाता है; \nप्रतिक्रियाशील शक्ति को अहस्ताक्षरित दिखाया गया है। \nहार्मोनिक्स, चरण असंतुलन, वोल्टेज की बूंदें, क्षणिक स्थितियां, कंडक्टर का आकार, सुरक्षा, सुरक्षा और विद्युत-कोड अनुपालन को मॉडल नहीं किया गया है। \nवास्तविक डिज़ाइन के लिए मापे गए उपकरण डेटा और योग्य इंजीनियरिंग समीक्षा का उपयोग करें। \nमान इस ब्राउज़र में रहते हैं."},"actions":{"calculate":"एसी पावर की गणना करें","reset":"रीसेट करें","copy":"परिणाम कॉपी करें","example":"400 वी, 10 ए और पीएफ 0.8 का प्रयास करें","result":"विद्युत अनुमान"},"messages":{"calculated":"एसी बिजली अनुमान की गणना की गई।","checkInputs":"वोल्टेज, करंट, पावर फैक्टर और समर्थित इकाइयों की जाँच करें।","activePower":"सक्रिय शक्ति (पी)","apparentPower":"स्पष्ट शक्ति (एस)","reactivePower":"प्रतिक्रियाशील शक्ति परिमाण (क्यू)","lineVoltage":"लाइन वोल्टेज","lineCurrent":"लाइन करंट","phaseVoltage":"चरण वोल्टेज","phaseCurrent":"चरण वर्तमान","powerFactor":"Power factor","formula":"फॉर्मूला","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"संतुलित तीन-चरण शक्ति का सूत्र क्या है?","answer":"लाइन-टू-लाइन वोल्टेज और लाइन करंट का उपयोग करते हुए, स्पष्ट शक्ति S = √3 × Vline × Iline है। \nसक्रिय शक्ति P = S × PF है। \nयह एक संतुलित साइनसॉइडल एसी प्रणाली मानता है।"},{"question":"स्टार और डेल्टा में क्या अंतर है?","answer":"एक संतुलित स्टार (वाईई) कनेक्शन के लिए, चरण वोल्टेज लाइन वोल्टेज को √3 से विभाजित किया जाता है और चरण धारा लाइन धारा के बराबर होती है। \nडेल्टा में, चरण वोल्टेज लाइन वोल्टेज के बराबर होता है और चरण धारा लाइन धारा को √3 से विभाजित किया जाता है। \nसमान पंक्ति मानों के लिए कुल शक्ति समान होती है।"},{"question":"क्या पावर फैक्टर सक्रिय पावर को प्रभावित करता है?","answer":"हाँ। \nसक्रिय शक्ति स्पष्ट शक्ति है जिसे शक्ति कारक से गुणा किया जाता है। \nकम पावर फैक्टर का मतलब समान लाइन वोल्टेज और करंट के लिए कम सक्रिय शक्ति है; \nप्रतिक्रियाशील-शक्ति परिमाण का अनुमान S × √(1 − PF²) से लगाया जाता है।"},{"question":"क्या मैं इसका उपयोग असंतुलित भार या विद्युत सुरक्षा डिज़ाइन के लिए कर सकता हूँ?","answer":"नहीं। यह एकल चरण या संतुलित तीन चरण के लिए एक आदर्श अनुमान है। \nयह असंतुलित चरणों, हार्मोनिक्स, वायरिंग, उपकरण रेटिंग, सुरक्षा, झटका या आग जोखिम, या स्थानीय विद्युत कोड का विश्लेषण नहीं करता है।"}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"ar":{"copyLanguage":"ar","name":"حاسبة القدرة ثلاثية الطور","title":"حاسبة القدرة ثلاثية الطور مجانًا | UsefulVerse","description":"احسب القدرة الفعالة والظاهرية والمتفاعلة للتيار المتردد أحادي أو ثلاثي الطور. مجانًا وفي متصفحك.","intro":"تقدير طاقة التيار المتردد من جهد الخط وتيار الخط وعامل الطاقة. \nقم بالتبديل بين الأنظمة أحادية الطور والأنظمة ثلاثية الطور المتوازنة، وقارن قيم طور النجم (wye) أو طور الدلتا.","howQuestion":"كيف أحسب الطاقة ثلاثية الطور؟","howAnswer":"لنظام متوازن ثلاثي الطور، الطاقة الظاهرة S = √3 × جهد الخط × تيار الخط، الطاقة النشطة P = S × عامل الطاقة، وحجم الطاقة التفاعلية Q = S × √(1 − PF²). \nالقدرة الظاهرة أحادية الطور هي V × I. تفترض هذه التقديرات وجود تيار متردد جيبي وحمل متوازن لوضع ثلاثي الطور.","privacyQuestion":"هل تم تحميل القيم الكهربائية الخاصة بي؟","privacyAnswer":"لا. يتم تشغيل الحساب في هذا المتصفح؛ \nلا يتم تحميل القيم التي تدخلها أو حفظها بواسطة هذه الأداة.","fields":{"system":"نظام التيار المتردد","singlePhase":"أحادي الطور","threePhase":"ثلاثي الأطوار (متوازن)","topology":"توصيلة ثلاثية الطور","star":"نجمة (Y)","delta":"مثلث (Δ)","lineVoltage":"جهد الخط","voltageUnit":"وحدة الجهد","volts":"فولت (V)","kilovolts":"كيلوفولت (kV)","lineCurrent":"تيار الخط","currentUnit":"وحدة التيار","amperes":"أمبير (A)","kiloamperes":"كيلوأمبير (kA)","powerFactor":"معامل القدرة (من 0 إلى 1)","accuracyNote":"تقدير التيار المتردد الجيبي المتوازن المثالي. \nيتم التعامل مع عامل القدرة على أنه حجم. \nتظهر القوة التفاعلية بدون توقيع. \nلم يتم تصميم التوافقيات، وعدم توازن الطور، وانخفاض الجهد، والظروف العابرة، وتحجيم الموصل، والحماية، والسلامة، والامتثال للكود الكهربائي. \nاستخدم بيانات المعدات المقاسة والمراجعة الهندسية المؤهلة للتصميمات الحقيقية. \nتبقى القيم في هذا المتصفح."},"actions":{"calculate":"حساب طاقة التيار المتردد","reset":"إعادة تعيين","copy":"نسخ النتائج","example":"جرب 400 فولت و10 أمبير وPF 0.8","result":"تقدير الطاقة"},"messages":{"calculated":"تم حساب تقدير طاقة التيار المتردد.","checkInputs":"فحص الجهد والتيار وعامل القدرة والوحدات المدعومة.","activePower":"القدرة الفعالة (P)","apparentPower":"القدرة الظاهرية (S)","reactivePower":"مقدار القدرة التفاعلية (Q)","lineVoltage":"جهد الخط","lineCurrent":"تيار الخط","phaseVoltage":"جهد الطور","phaseCurrent":"تيار الطور","powerFactor":"معامل القدرة","formula":"الصيغة","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"ما هي صيغة الطاقة المتوازنة ثلاثية الطور؟","answer":"باستخدام جهد خط إلى خط وتيار الخط، تكون الطاقة الظاهرة S = √3 × Vline × Iline. \nالطاقة النشطة هي P = S × PF. \nهذا يفترض وجود نظام تيار متردد جيبي متوازن."},{"question":"ما الفرق بين النجم والدلتا؟","answer":"لاتصال نجمي متوازن (wye)، جهد الطور هو جهد الخط مقسومًا على √3 وتيار الطور يساوي تيار الخط. \nفي الدلتا، جهد الطور يساوي جهد الخط وتيار الطور هو تيار الخط مقسومًا على √3. \nإجمالي الطاقة لنفس قيم الخط هو نفسه."},{"question":"هل يؤثر عامل القدرة على الطاقة النشطة؟","answer":"نعم. \nالقوة النشطة هي القوة الظاهرة مضروبة في عامل القدرة. \nعامل الطاقة الأقل يعني طاقة أقل نشاطًا لنفس خط الجهد والتيار؛ \nيتم تقدير حجم القدرة التفاعلية من S × √(1 - PF²)."},{"question":"هل يمكنني استخدام هذا للأحمال غير المتوازنة أو تصميم السلامة الكهربائية؟","answer":"لا. هذا تقدير مثالي لمرحلة واحدة أو ثلاث مراحل متوازنة. \nولا يقوم بتحليل المراحل غير المتوازنة، أو التوافقيات، أو الأسلاك، أو تقييمات المعدات، أو الحماية، أو مخاطر الصدمات أو الحرائق، أو الرموز الكهربائية المحلية.\n\nتمت الموافقة على"}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"zh":{"copyLanguage":"zh","name":"三相功率计算器","title":"三相功率计算器 | UsefulVerse","description":"计算单相或三相交流有功功率、视在功率和无功功率。\n免费、无限制并在您的浏览器中本地计算。","intro":"根据线路电压、线路电流和功率因数估算交流功率。\n在单相和平衡三相系统之间切换，并比较星形 (Y) 或三角形相位值。","howQuestion":"如何计算三相功率？","howAnswer":"对于平衡三相系统，视在功率 S = √3 × 线电压 × 线电流，有功功率 P = S × 功率因数，无功功率大小 Q = S × √(1 − PF²)。\n单相视在功率为 V × I。这些估计值假定三相模式为正弦交流电和平衡负载。","privacyQuestion":"我的电气值是否已上传？","privacyAnswer":"否。计算在此浏览器中运行；\n此工具不会上传或保存您输入的值。","fields":{"system":"交流系统","singlePhase":"单相","threePhase":"三相（平衡）","topology":"三相连接","star":"星形/Y 形","delta":"达美","lineVoltage":"线电压","voltageUnit":"电压单位","volts":"伏 (V)","kilovolts":"千伏 (kV)","lineCurrent":"线电流","currentUnit":"当前单位","amperes":"安培 (A)","kiloamperes":"千安 (kA)","powerFactor":"功率因数（0 至 1）","accuracyNote":"理想平衡正弦交流电估计。\n功率因数被视为一个量级；\n无功功率显示为无符号。\n谐波、相位不平衡、电压降、瞬态条件、导体尺寸、保护、安全和电气规范合规性均未建模。\n使用测量的设备数据和合格的工程审查进行实际设计。\n值保留在此浏览器中。"},"actions":{"calculate":"计算交流功率","reset":"重置","copy":"复制结果","example":"尝试 400 V、10 A 和 PF 0.8","result":"功率估算"},"messages":{"calculated":"已计算交流功率估算值。","checkInputs":"检查电压、电流、功率因数和支持的单位。","activePower":"有功功率 (P)","apparentPower":"视在功率（S）","reactivePower":"无功功率幅度 (Q)","lineVoltage":"线电压","lineCurrent":"线电流","phaseVoltage":"相电压","phaseCurrent":"相电流","powerFactor":"功率因数","formula":"公式","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"平衡三相功率的公式是什么？","answer":"使用线间电压和线电流，视在功率为 S = √3 × Vline × Iline。\n有功功率为P=S×PF。\n这假设一个平衡的正弦交流系统。"},{"question":"星形和三角形有什么区别？","answer":"对于平衡星形 (Y) 连接，相电压为线电压除以 √3，相电流等于线电流。\n在三角形中，相电压等于线电压，相电流等于线电流除以√3。\n相同线路值的总功率是相同的。"},{"question":"功率因数影响有功功率吗？","answer":"是的。\n有功功率是视在功率乘以功率因数。\n功率因数越低，意味着相同线路电压和电流下的有功功率越少；\n无功功率大小根据 S × √(1 − PF²) 估算。"},{"question":"我可以将其用于不平衡负载或电气安全设计吗？","answer":"否。这是单相或平衡三相的理想估计。\n它不会分析不平衡相位、谐波、接线、设备额定值、保护、冲击或火灾风险或当地电气规范。"}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"bn":{"copyLanguage":"bn","name":"থ্রি ফেজ পাওয়ার ক্যালকুলেটর","title":"থ্রি ফেজ পাওয়ার ক্যালকুলেটর | UsefulVerse","description":"একক- বা তিন-ফেজ AC সক্রিয়, আপাত এবং প্রতিক্রিয়াশীল শক্তি গণনা করুন। \nআপনার ব্রাউজারে বিনামূল্যে, সীমাহীন এবং স্থানীয়ভাবে গণনা করা।","intro":"লাইন ভোল্টেজ, লাইন কারেন্ট এবং পাওয়ার ফ্যাক্টর থেকে এসি পাওয়ার অনুমান করুন। \nএকক-ফেজ এবং সুষম তিন-ফেজ সিস্টেমের মধ্যে স্যুইচ করুন এবং তারকা (wye) বা ডেল্টা ফেজ মান তুলনা করুন।","howQuestion":"আমি কিভাবে তিন-ফেজ শক্তি গণনা করব?","howAnswer":"একটি সুষম থ্রি-ফেজ সিস্টেমের জন্য, আপাত শক্তি S = √3 × লাইন ভোল্টেজ × লাইন কারেন্ট, সক্রিয় শক্তি P = S × পাওয়ার ফ্যাক্টর, এবং প্রতিক্রিয়াশীল-শক্তি মাত্রা Q = S × √(1 − PF²)। \nএকক-ফেজ আপাত শক্তি হল V × I। এই অনুমানগুলি সাইনোসয়েডাল এসি এবং তিন-ফেজ মোডের জন্য একটি সুষম লোড অনুমান করে।","privacyQuestion":"আমার বৈদ্যুতিক মান কি আপলোড করা হয়েছে?","privacyAnswer":"নং। গণনা এই ব্রাউজারে চলে; \nআপনার প্রবেশ করা মান এই টুল দ্বারা আপলোড বা সংরক্ষণ করা হয় না।","fields":{"system":"এসি সিস্টেম","singlePhase":"একক ফেজ","threePhase":"তিন ফেজ (সুষম)","topology":"তিন-ফেজ সংযোগ","star":"স্টার/ওয়াই","delta":"ডেল্টা","lineVoltage":"লাইন ভোল্টেজ","voltageUnit":"ভোল্টেজ ইউনিট","volts":"ভোল্ট (V)","kilovolts":"কিলোভোল্ট (kV)","lineCurrent":"লাইন বর্তমান","currentUnit":"বর্তমান ইউনিট","amperes":"অ্যাম্পিয়ার (A)","kiloamperes":"Kiloamperes (kA)","powerFactor":"পাওয়ার ফ্যাক্টর (0 থেকে 1)","accuracyNote":"আদর্শ সুষম সাইনোসয়েডাল এসি অনুমান। \nপাওয়ার ফ্যাক্টর একটি মাত্রা হিসাবে গণ্য করা হয়; \nপ্রতিক্রিয়াশীল শক্তি স্বাক্ষরবিহীন দেখানো হয়। \nহারমোনিক্স, ফেজ ভারসাম্যহীনতা, ভোল্টেজ ড্রপ, ক্ষণস্থায়ী অবস্থা, কন্ডাকটর সাইজিং, সুরক্ষা, নিরাপত্তা এবং বৈদ্যুতিক-কোড সম্মতি মডেল করা হয় না। \nবাস্তব ডিজাইনের জন্য পরিমাপ করা যন্ত্রপাতি ডেটা এবং যোগ্য প্রকৌশল পর্যালোচনা ব্যবহার করুন। \nমান এই ব্রাউজারে থাকে।"},"actions":{"calculate":"AC পাওয়ার গণনা করুন","reset":"রিসেট করুন","copy":"ফলাফল কপি করুন","example":"400 V, 10 A এবং PF 0.8 ব্যবহার করে দেখুন","result":"পাওয়ার অনুমান"},"messages":{"calculated":"এসি পাওয়ার অনুমান গণনা করা হয়েছে।","checkInputs":"ভোল্টেজ, কারেন্ট, পাওয়ার ফ্যাক্টর এবং সমর্থিত ইউনিট চেক করুন।","activePower":"সক্রিয় শক্তি (P)","apparentPower":"স্পষ্ট শক্তি (এস)","reactivePower":"প্রতিক্রিয়াশীল শক্তির মাত্রা (Q)","lineVoltage":"লাইন ভোল্টেজ","lineCurrent":"লাইন বর্তমান","phaseVoltage":"ফেজ ভোল্টেজ","phaseCurrent":"ফেজ বর্তমান","powerFactor":"পাওয়ার ফ্যাক্টর","formula":"সূত্র","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"সুষম তিন-পর্যায়ের শক্তির সূত্র কী?","answer":"লাইন-টু-লাইন ভোল্টেজ এবং লাইন কারেন্ট ব্যবহার করে, আপাত শক্তি হল S = √3 × Vline × Iline। \nসক্রিয় শক্তি হল P = S × PF। \nএটি একটি সুষম সাইনোসয়েডাল এসি সিস্টেম অনুমান করে।"},{"question":"তারকা এবং ব-দ্বীপের মধ্যে পার্থক্য কী?","answer":"একটি সুষম তারকা (wye) সংযোগের জন্য, ফেজ ভোল্টেজ হল লাইন ভোল্টেজ যা √3 দ্বারা বিভক্ত এবং ফেজ কারেন্ট লাইন কারেন্টের সমান। \nব-দ্বীপে, ফেজ ভোল্টেজ লাইন ভোল্টেজের সমান এবং ফেজ কারেন্ট হল লাইন কারেন্টকে √3 দ্বারা ভাগ করা হয়। \nএকই লাইনের মানগুলির জন্য মোট শক্তি একই।"},{"question":"পাওয়ার ফ্যাক্টর কি সক্রিয় শক্তিকে প্রভাবিত করে?","answer":"হ্যাঁ। \nসক্রিয় শক্তি পাওয়ার ফ্যাক্টর দ্বারা গুণিত আপাত শক্তি। \nলোয়ার পাওয়ার ফ্যাক্টর মানে একই লাইন ভোল্টেজ এবং কারেন্টের জন্য কম সক্রিয় শক্তি; \nপ্রতিক্রিয়াশীল-শক্তির মাত্রা S × √(1 − PF²) থেকে অনুমান করা হয়।"},{"question":"আমি কি ভারসাম্যহীন লোড বা বৈদ্যুতিক সুরক্ষা ডিজাইনের জন্য এটি ব্যবহার করতে পারি?","answer":"নং। এটি একক ফেজ বা সুষম তিন পর্বের জন্য একটি আদর্শ অনুমান। \nএটি ভারসাম্যহীন পর্যায়, হারমোনিক্স, ওয়্যারিং, সরঞ্জাম রেটিং, সুরক্ষা, শক বা আগুনের ঝুঁকি, বা স্থানীয় বৈদ্যুতিক কোডগুলি বিশ্লেষণ করে না।"}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"ru":{"copyLanguage":"ru","name":"Калькулятор трехфазной мощности","title":"Калькулятор трехфазной мощности | UsefulVerse","description":"Рассчитайте активную, полную и реактивную мощность одно- или трехфазного переменного тока. \nБесплатно, без ограничений и рассчитывается локально в вашем...","intro":"Оцените мощность переменного тока по сетевому напряжению, линейному току и коэффициенту мощности. \nПереключайтесь между однофазными и сбалансированными трехфазными системами и сравнивайте значения фаз звезды (звезда) или треугольника.","howQuestion":"Как рассчитать трехфазную мощность?","howAnswer":"Для сбалансированной трехфазной системы полная мощность S = √3 × линейное напряжение × сетевой ток, активная мощность P = S × коэффициент мощности и величина реактивной мощности Q = S × √(1 − PF²). \nПолная мощность однофазной сети равна V × I. Эти оценки предполагают синусоидальный переменный ток и сбалансированную нагрузку для трехфазного режима.","privacyQuestion":"Загружены ли мои электрические значения?","privacyAnswer":"Нет. Расчет выполняется в этом браузере; \nВведенные вами значения не загружаются и не сохраняются этим инструментом.","fields":{"system":"Система переменного тока","singlePhase":"Однофазный","threePhase":"Трехфазный (сбалансированный)","topology":"Трехфазное подключение","star":"Звезда/звездочка","delta":"Дельта","lineVoltage":"Сетевое напряжение","voltageUnit":"Блок напряжения","volts":"Вольт (В)","kilovolts":"Киловольты (кВ)","lineCurrent":"Линейный ток","currentUnit":"Текущая единица","amperes":"Ампер (А)","kiloamperes":"Килоампер (кА)","powerFactor":"Коэффициент мощности (от 0 до 1)","accuracyNote":"Идеально сбалансированная оценка синусоидального переменного тока. \nКоэффициент мощности рассматривается как величина; \nреактивная мощность указывается без знака. \nГармоники, перекос фаз, падения напряжения, переходные условия, размеры проводников, защита, безопасность и соответствие электротехническим нормам не моделируются. \nИспользуйте данные измерений оборудования и квалифицированную инженерную оценку для реальных проектов. \nЗначения остаются в этом браузере."},"actions":{"calculate":"Рассчитать мощность переменного тока","reset":"Сброс","copy":"Копировать результаты","example":"Попробуйте 400 В, 10 А и коэффициент мощности 0,8.","result":"Оценка мощности"},"messages":{"calculated":"Рассчитана оценка мощности переменного тока.","checkInputs":"Проверьте напряжение, ток, коэффициент мощности и поддерживаемые устройства.","activePower":"Активная мощность (P)","apparentPower":"Полная мощность (S)","reactivePower":"Величина реактивной мощности (Q)","lineVoltage":"Сетевое напряжение","lineCurrent":"Линейный ток","phaseVoltage":"Фазное напряжение","phaseCurrent":"Фазный ток","powerFactor":"Коэффициент мощности","formula":"Формула","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"Какова формула сбалансированной трехфазной мощности?","answer":"Используя линейное напряжение и линейный ток, полная мощность равна S = √3 × Vline × Iline. \nАктивная мощность равна P = S × PF. \nЭто предполагает сбалансированную синусоидальную систему переменного тока."},{"question":"В чем разница между звездой и треугольником?","answer":"При симметричном соединении звездой фазное напряжение равно линейному напряжению, деленному на √3, а фазный ток равен линейному току. \nВ схеме треугольника фазное напряжение равно линейному напряжению, а фазный ток — это линейному току, деленному на √3. \nСуммарная мощность для одинаковых значений линий одинакова."},{"question":"Влияет ли коэффициент мощности на активную мощность?","answer":"Да. \nАктивная мощность – это полная мощность, умноженная на коэффициент мощности. \nБолее низкий коэффициент мощности означает меньшую активную мощность при тех же сетевом напряжении и токе; \nВеличина реактивной мощности оценивается по формуле S × √(1 − PF²)."},{"question":"Могу ли я использовать это для несбалансированных нагрузок или электробезопасности?","answer":"Нет. Это идеализированная оценка для однофазной или сбалансированной трехфазной сети. \nОн не анализирует несбалансированные фазы, гармоники, проводку, номиналы оборудования, защиту, риск поражения электрическим током или пожаром, а также местные электротехнические нормы и правила."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"ur":{"copyLanguage":"ur","name":"تھری فیز پاور کیلکولیٹر","title":"تھری فیز پاور کیلکولیٹر | UsefulVerse","description":"سنگل یا تھری فیز AC فعال، ظاہری اور رد عمل والی طاقت کا حساب لگائیں۔ \nآپ کے براؤزر میں مقامی طور پر مفت، لامحدود اور حساب کتاب۔","intro":"لائن وولٹیج، لائن کرنٹ اور پاور فیکٹر سے AC پاور کا اندازہ لگائیں۔ \nسنگل فیز اور متوازن تھری فیز سسٹمز کے درمیان سوئچ کریں، اور اسٹار (وائی) یا ڈیلٹا فیز ویلیوز کا موازنہ کریں۔","howQuestion":"میں تھری فیز پاور کا حساب کیسے لگا سکتا ہوں؟","howAnswer":"متوازن تھری فیز سسٹم کے لیے، ظاہری طاقت S = √3 × لائن وولٹیج × لائن کرنٹ، ایکٹو پاور P = S × پاور فیکٹر، اور ری ایکٹو پاور کی شدت Q = S × √(1 − PF²)۔ \nسنگل فیز کی ظاہری طاقت V × I ہے۔ یہ تخمینے تین فیز موڈ کے لیے سائنوسائیڈل AC اور ایک متوازن بوجھ فرض کرتے ہیں۔","privacyQuestion":"کیا میری برقی قدریں اپ لوڈ ہیں؟","privacyAnswer":"نمبر۔ حساب اس براؤزر میں چلتا ہے۔ \nآپ جو قدریں داخل کرتے ہیں وہ اس ٹول کے ذریعے اپ لوڈ یا محفوظ نہیں کی جاتی ہیں۔","fields":{"system":"AC سسٹم","singlePhase":"سنگل فیز","threePhase":"تین فیز (متوازن)","topology":"تھری فیز کنکشن","star":"Star/wye","delta":"ڈیلٹا","lineVoltage":"لائن وولٹیج","voltageUnit":"وولٹیج یونٹ","volts":"وولٹ (V)","kilovolts":"کلو وولٹس (kV)","lineCurrent":"لائن کرنٹ","currentUnit":"موجودہ یونٹ","amperes":"Amperes (A)","kiloamperes":"کلو امپیئرز (کے اے)","powerFactor":"پاور فیکٹر (0 سے 1)","accuracyNote":"مثالی متوازن سائنوسائیڈل AC تخمینہ۔ \nپاور فیکٹر کو ایک شدت کے طور پر سمجھا جاتا ہے۔ \nرد عمل کی طاقت کو غیر دستخط شدہ دکھایا گیا ہے۔ \nہارمونکس، مرحلے میں عدم توازن، وولٹیج کے قطرے، عارضی حالات، کنڈکٹر کا سائز، تحفظ، حفاظت اور الیکٹریکل کوڈ کی تعمیل کو ماڈل نہیں بنایا گیا ہے۔ \nحقیقی ڈیزائن کے لیے ماپا آلات کا ڈیٹا اور اہل انجینئرنگ کا جائزہ استعمال کریں۔ \nاقدار اس براؤزر میں رہتی ہیں۔"},"actions":{"calculate":"AC پاور کا حساب لگائیں۔","reset":"ری سیٹ کریں۔","copy":"نتائج کاپی کریں۔","example":"400 V، 10 A اور PF 0.8 آزمائیں","result":"پاور کا تخمینہ"},"messages":{"calculated":"AC پاور کا تخمینہ لگایا گیا۔","checkInputs":"وولٹیج، کرنٹ، پاور فیکٹر اور معاون یونٹس چیک کریں۔","activePower":"فعال طاقت (P)","apparentPower":"ظاہری طاقت (S)","reactivePower":"رد عمل کی طاقت کی شدت (Q)","lineVoltage":"لائن وولٹیج","lineCurrent":"لائن کرنٹ","phaseVoltage":"فیز وولٹیج","phaseCurrent":"فیز کرنٹ","powerFactor":"پاور فیکٹر","formula":"فارمولا","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"متوازن تھری فیز پاور کا فارمولا کیا ہے؟","answer":"لائن ٹو لائن وولٹیج اور لائن کرنٹ کا استعمال کرتے ہوئے، ظاہری طاقت S = √3 × Vline × Iline ہے۔ \nفعال طاقت P = S × PF ہے۔ \nیہ ایک متوازن sinusoidal AC نظام کو فرض کرتا ہے۔"},{"question":"ستارے اور ڈیلٹا میں کیا فرق ہے؟","answer":"متوازن ستارہ (wye) کنکشن کے لیے، فیز وولٹیج لائن وولٹیج ہے جسے √3 سے تقسیم کیا جاتا ہے اور فیز کرنٹ لائن کرنٹ کے برابر ہوتا ہے۔ \nڈیلٹا میں، فیز وولٹیج لائن وولٹیج کے برابر ہے اور فیز کرنٹ لائن کرنٹ کو √3 سے تقسیم کیا جاتا ہے۔ \nایک ہی لائن کی قدروں کی کل طاقت ایک جیسی ہے۔"},{"question":"کیا پاور فیکٹر فعال پاور کو متاثر کرتا ہے؟","answer":"ہاں۔ \nفعال طاقت ظاہری طاقت ہے جسے پاور فیکٹر سے ضرب کیا جاتا ہے۔ \nلوئر پاور فیکٹر کا مطلب ہے ایک ہی لائن وولٹیج اور کرنٹ کے لیے کم فعال پاور۔ \nرد عمل کی طاقت کا اندازہ S × √(1 − PF²) سے لگایا گیا ہے۔"},{"question":"کیا میں اسے غیر متوازن بوجھ یا الیکٹریکل سیفٹی ڈیزائن کے لیے استعمال کر سکتا ہوں؟","answer":"نمبر۔ یہ سنگل فیز یا متوازن تھری فیز کے لیے ایک مثالی تخمینہ ہے۔ \nیہ غیر متوازن مراحل، ہارمونکس، وائرنگ، آلات کی درجہ بندی، تحفظ، جھٹکا یا آگ کے خطرے، یا مقامی برقی کوڈز کا تجزیہ نہیں کرتا ہے۔"}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"tr":{"copyLanguage":"tr","name":"Üç Fazlı Güç Hesaplayıcı","title":"Üç Fazlı Güç Hesaplayıcı | UsefulVerse","description":"Tek veya üç fazlı AC aktif, görünür ve reaktif gücü hesaplayın. \nÜcretsiz, sınırsız ve tarayıcınızda yerel olarak hesaplanır.","intro":"Hat voltajı, hat akımı ve güç faktöründen AC gücünü tahmin edin. \nTek fazlı ve dengeli üç fazlı sistemler arasında geçiş yapın ve yıldız (wye) veya delta fazı değerlerini karşılaştırın.","howQuestion":"Üç fazlı gücü nasıl hesaplarım?","howAnswer":"Dengeli bir üç fazlı sistem için, görünen güç S = √3 × hat voltajı × hat akımı, aktif güç P = S × güç faktörü ve reaktif güç büyüklüğü Q = S × √(1 − PF²). \nTek fazlı görünür güç V × I'dir. Bu tahminler sinüzoidal AC ve üç fazlı mod için dengeli bir yük varsaymaktadır.","privacyQuestion":"Elektrik değerlerim yüklendi mi?","privacyAnswer":"Hayır. Hesaplama bu tarayıcıda çalışır; \ngirdiğiniz değerler bu araç tarafından yüklenmez veya kaydedilmez.","fields":{"system":"AC sistemi","singlePhase":"Tek fazlı","threePhase":"Trifaze (dengeli)","topology":"Üç fazlı bağlantı","star":"Yıldız / yıldız","delta":"Delta","lineVoltage":"Hat voltajı","voltageUnit":"Gerilim ünitesi","volts":"Volt (V)","kilovolts":"Kilovolt (kV)","lineCurrent":"Hat akımı","currentUnit":"Mevcut birim","amperes":"Amper (A)","kiloamperes":"Kiloamper (kA)","powerFactor":"Güç faktörü (0 - 1)","accuracyNote":"İdeal dengeli sinüzoidal AC tahmini. \nGüç faktörü bir büyüklük olarak ele alınır; \nreaktif güç işaretsiz olarak gösterilir. \nHarmonikler, faz dengesizliği, voltaj düşüşleri, geçici koşullar, iletken boyutu, koruma, güvenlik ve elektrik kodu uyumluluğu modellenmemiştir. \nGerçek tasarımlar için ölçülen ekipman verilerini ve nitelikli mühendislik incelemesini kullanın. \nDeğerler bu tarayıcıda kalır."},"actions":{"calculate":"AC gücünü hesaplayın","reset":"Sıfırla","copy":"Sonuçları kopyala","example":"400 V, 10 A ve PF 0,8'i deneyin","result":"Güç tahmini"},"messages":{"calculated":"AC güç tahmini hesaplandı.","checkInputs":"Gerilimi, akımı, güç faktörünü ve desteklenen birimleri kontrol edin.","activePower":"Aktif güç (P)","apparentPower":"Görünür güç (S)","reactivePower":"Reaktif güç büyüklüğü (Q)","lineVoltage":"Hat voltajı","lineCurrent":"Hat akımı","phaseVoltage":"Faz gerilimi","phaseCurrent":"Faz akımı","powerFactor":"Güç faktörü","formula":"Formül","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"Dengeli üç fazlı gücün formülü nedir?","answer":"Hattan hatta gerilim ve hat akımı kullanıldığında görünen güç S = √3 × Vhat × Ihattır. \nAktif güç P = S × PF'dir. \nBu dengeli bir sinüzoidal AC sistemi varsayar."},{"question":"Yıldız ve delta arasındaki fark nedir?","answer":"Dengeli yıldız (wye) bağlantısı için, faz voltajı hat voltajının √3'e bölümüdür ve faz akımı hat akımına eşittir. \nDelta cinsinden, faz voltajı hat voltajına eşittir ve faz akımı hat akımının √3'e bölünmesiyle elde edilir. \nAynı hat değerleri için toplam güç aynıdır."},{"question":"Güç faktörü aktif gücü etkiler mi?","answer":"Evet. \nAktif güç, görünen gücün güç faktörüyle çarpımıdır. \nDaha düşük güç faktörü, aynı hat voltajı ve akımı için daha az aktif güç anlamına gelir; \nreaktif güç büyüklüğü S × √(1 − PF²) cinsinden tahmin edilir."},{"question":"Bunu dengesiz yükler veya elektriksel güvenlik tasarımı için kullanabilir miyim?","answer":"Hayır. Bu, tek fazlı veya dengeli üç fazlı için idealleştirilmiş bir tahmindir. \nDengesiz fazları, harmonikleri, kabloları, ekipman derecelendirmelerini, korumayı, şok veya yangın riskini veya yerel elektrik yasalarını analiz etmez."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"vi":{"copyLanguage":"vi","name":"Máy tính công suất ba pha","title":"Máy tính công suất ba pha | UsefulVerse","description":"Tính toán công suất tác dụng, biểu kiến và phản kháng AC một pha hoặc ba pha. \nMiễn phí, không giới hạn và được tính toán cục bộ trong trình duyệt của bạn.","intro":"Ước tính nguồn điện xoay chiều từ điện áp đường dây, dòng điện đường dây và hệ số công suất. \nChuyển đổi giữa các hệ thống ba pha một pha và ba pha cân bằng, đồng thời so sánh các giá trị pha sao (wye) hoặc pha tam giác.","howQuestion":"Làm cách nào để tính công suất ba pha?","howAnswer":"Đối với hệ thống ba pha cân bằng, công suất biểu kiến ​​S = √3 × điện áp đường dây × dòng điện đường dây, công suất tác dụng P = S × hệ số công suất và cường độ công suất phản kháng Q = S × √(1 − PF²). \nCông suất biểu kiến ​​một pha là V × I. Những ước tính này giả định AC hình sin và tải cân bằng cho chế độ ba pha.","privacyQuestion":"Giá trị điện của tôi có được tải lên không?","privacyAnswer":"Không. Phép tính chạy trong trình duyệt này; \ncác giá trị bạn nhập không được tải lên hoặc lưu bởi công cụ này.\n\nHệ thống AC","fields":{"system":"AC system","singlePhase":"Một pha","threePhase":"Ba pha (cân bằng)","topology":"Kết nối ba pha","star":"Sao / wye","delta":"Đồng bằng","lineVoltage":"Điện áp đường dây","voltageUnit":"Đơn vị điện áp","volts":"Vôn (V)","kilovolts":"Kilôvôn (kV)","lineCurrent":"Dòng điện","currentUnit":"Đơn vị hiện tại","amperes":"Ampe (A)","kiloamperes":"Kiloampe (kA)","powerFactor":"Hệ số công suất (0 đến 1)","accuracyNote":"Ước tính AC hình sin cân bằng lý tưởng. \nHệ số công suất được coi là độ lớn; \ncông suất phản kháng được hiển thị không dấu. \nSóng hài, mất cân bằng pha, sụt áp, điều kiện nhất thời, kích thước dây dẫn, bảo vệ, an toàn và tuân thủ mã điện không được mô hình hóa. \nSử dụng dữ liệu thiết bị đo được và đánh giá kỹ thuật đủ tiêu chuẩn cho các thiết kế thực tế. \nCác giá trị vẫn ở trong trình duyệt này."},"actions":{"calculate":"Tính toán nguồn điện xoay chiều","reset":"Đặt lại","copy":"Sao chép kết quả","example":"Thử 400 V, 10 A và PF 0,8","result":"Ước tính công suất\n\nĐã tính toán ước tính nguồn điện AC"},"messages":{"calculated":".","checkInputs":"Kiểm tra điện áp, dòng điện, hệ số công suất và các bộ phận được hỗ trợ.","activePower":"Công suất hoạt động (P)","apparentPower":"Công suất biểu kiến (S)","reactivePower":"Độ lớn công suất phản kháng (Q)","lineVoltage":"Điện áp đường dây","lineCurrent":"Dòng điện","phaseVoltage":"Điện áp pha","phaseCurrent":"Dòng pha","powerFactor":"Hệ số công suất","formula":"Công thức","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"Công thức cân bằng điện ba pha là gì?","answer":"Sử dụng điện áp và dòng điện giữa các dây, công suất biểu kiến ​​là S = √3 × Vline × Iline. \nCông suất tác dụng là P = S × PF. \nĐiều này giả định một hệ thống AC hình sin cân bằng."},{"question":"Sự khác biệt giữa ngôi sao và hình tam giác là gì?","answer":"Đối với kết nối sao cân bằng (wye), điện áp pha là điện áp đường dây chia cho √3 và dòng điện pha bằng dòng điện đường dây. \nỞ delta, điện áp pha bằng điện áp đường dây và dòng điện pha là dòng điện chia cho √3. \nTổng công suất cho cùng một giá trị dòng là như nhau."},{"question":"Hệ số công suất có ảnh hưởng đến công suất tác dụng không?","answer":"Có. \nCông suất tác dụng là công suất biểu kiến ​​nhân với hệ số công suất. \nHệ số công suất thấp hơn có nghĩa là công suất tác dụng ít hơn đối với cùng điện áp và dòng điện; \ncường độ công suất phản kháng được ước tính từ S × √(1 - PF²)."},{"question":"Tôi có thể sử dụng điều này cho tải không cân bằng hoặc thiết kế an toàn điện không?","answer":"Không. Đây là ước tính lý tưởng cho một pha hoặc ba pha cân bằng. \nNó không phân tích các pha không cân bằng, sóng hài, hệ thống dây điện, xếp hạng thiết bị, khả năng bảo vệ, nguy cơ sốc hoặc hỏa hoạn hoặc mã điện cục bộ."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"it":{"copyLanguage":"it","name":"Calcolatore di potenza trifase","title":"Calcolatore di potenza trifase | UsefulVerse","description":"Calcola la potenza attiva, apparente e reattiva AC monofase o trifase. \nGratuito, illimitato e calcolato localmente nel tuo browser.","intro":"Stima della potenza CA in base alla tensione di linea, alla corrente di linea e al fattore di potenza. \nPassa dai sistemi monofase a quelli trifase bilanciati e confronta i valori della fase stella (stella) o triangolo.","howQuestion":"Come calcolo la potenza trifase?","howAnswer":"Per un sistema trifase equilibrato, potenza apparente S = √3 × tensione di linea × corrente di linea, potenza attiva P = S × fattore di potenza e grandezza della potenza reattiva Q = S × √(1 − PF²). \nLa potenza apparente monofase è V × I. Queste stime presuppongono una CA sinusoidale e un carico bilanciato per la modalità trifase.","privacyQuestion":"I miei valori elettrici vengono caricati?","privacyAnswer":"No. Il calcolo viene eseguito in questo browser; \ni valori immessi non vengono caricati o salvati da questo strumento.","fields":{"system":"Impianto AC","singlePhase":"Monofase","threePhase":"Trifase (equilibrato)","topology":"Collegamento trifase","star":"Stella/stella","delta":"Delta","lineVoltage":"Tensione di linea","voltageUnit":"Unità di tensione","volts":"Volt (V)","kilovolts":"Kilovolt (kV)","lineCurrent":"Corrente di linea","currentUnit":"Unità attuale","amperes":"Ampere (A)","kiloamperes":"Kiloampere (kA)","powerFactor":"Fattore di potenza (da 0 a 1)","accuracyNote":"Stima AC sinusoidale bilanciata ideale. \nIl fattore di potenza viene trattato come una grandezza; \nla potenza reattiva è mostrata senza segno. \nNon vengono modellati le armoniche, lo squilibrio di fase, le cadute di tensione, le condizioni transitorie, il dimensionamento dei conduttori, la protezione, la sicurezza e la conformità alle norme elettriche. \nUtilizza i dati misurati delle apparecchiature e la revisione tecnica qualificata per progetti reali. \nI valori rimangono in questo browser."},"actions":{"calculate":"Calcola la potenza CA","reset":"Ripristina","copy":"Copia risultati","example":"Prova 400 V, 10 A e PF 0,8","result":"Stima della potenza"},"messages":{"calculated":"Stima della potenza CA calcolata.","checkInputs":"Controllare tensione, corrente, fattore di potenza e unità supportate.","activePower":"Potenza attiva (P)","apparentPower":"Potenza apparente (S)","reactivePower":"Grandezza potenza reattiva (Q)","lineVoltage":"Tensione di linea","lineCurrent":"Corrente di linea","phaseVoltage":"Tensione di fase","phaseCurrent":"Corrente di fase","powerFactor":"Fattore di potenza","formula":"Formula","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"Qual è la formula per ottenere una potenza trifase equilibrata?","answer":"Utilizzando la tensione concatenata e la corrente di linea, la potenza apparente è S = √3 × Vlinea × Ilinea. \nLa potenza attiva è P = S × PF. \nCiò presuppone un sistema AC sinusoidale bilanciato."},{"question":"Qual è la differenza tra stella e triangolo?","answer":"Per un collegamento a stella (stella) bilanciato, la tensione di fase è la tensione di linea divisa per √3 e la corrente di fase è uguale alla corrente di linea. \nNel triangolo, la tensione di fase è uguale alla tensione di linea e la corrente di fase è la corrente di linea divisa per √3. \nLa potenza totale per gli stessi valori di linea è la stessa."},{"question":"Il fattore di potenza influisce sulla potenza attiva?","answer":"Sì. \nLa potenza attiva è la potenza apparente moltiplicata per il fattore di potenza. \nUn fattore di potenza inferiore significa meno potenza attiva a parità di tensione e corrente di linea; \nla magnitudo della potenza reattiva è stimata da S × √ (1 − PF²)."},{"question":"Posso usarlo per carichi sbilanciati o progetti di sicurezza elettrica?","answer":"No. Questa è una stima ideale per monofase o trifase bilanciata. \nNon analizza fasi sbilanciate, armoniche, cablaggi, valori nominali delle apparecchiature, protezione, rischio di scosse o incendi o codici elettrici locali."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"zh_tw":{"copyLanguage":"zh_tw","name":"三相功率計算器","title":"三相功率計算器 | UsefulVerse","description":"計算單相或三相交流有功功率、視在功率和無功功率。免費、無限制並在您的瀏覽器中本地計算。","intro":"根據線路電壓、線路電流和功率因數估算交流功率。在單相和平衡三相繫統之間切換，並比較星形 (Y) 或三角形相位值。","howQuestion":"如何計算三相功率？","howAnswer":"平衡三相繫統，視在功率 S = √3 × 線電壓 × 線電流，有功功率 P = S × 功率因數，無功功率大小 Q = S × √(1 − PF²)。單相視在功率為 V × I。這些估計值假定三相模式為正弦交流電和平衡負載。","privacyQuestion":"我的電氣值是否已上傳？","privacyAnswer":"否。計算在此瀏覽器中運作；此工具不會上傳或儲存您輸入的值。","fields":{"system":"交流系統","singlePhase":"單相","threePhase":"三相（平衡）","topology":"三相連接","star":"星形/Y 形","delta":"達美","lineVoltage":"線電壓","voltageUnit":"電壓單位","volts":"伏特 (V)","kilovolts":"千伏特 (kV)","lineCurrent":"線電流","currentUnit":"當前單位","amperes":"安培 (A)","kiloamperes":"千安 (kA)","powerFactor":"功率因數（0 至 1）","accuracyNote":"理想平衡正弦交流電估計。功率因數被視為一個量級；無功功率顯示為無符號。諧波、相位不平衡、電壓降、瞬態條件、導體尺寸、保護、安全性和電氣規範合規性均未建模。使用測量的設備數據和合格的工程審查進行實際設計。值保留在此瀏覽器中。"},"actions":{"calculate":"計算交流功率","reset":"重置","copy":"複製結果","example":"試試 400 V、10 A 和 PF 0.8","result":"功率估算"},"messages":{"calculated":"已計算交流功率估算值。","checkInputs":"檢查電壓、電流、功率因數和支援的單位。","activePower":"有功功率 (P)","apparentPower":"視在功率（S）","reactivePower":"無功功率幅度 (Q)","lineVoltage":"線電壓","lineCurrent":"線電流","phaseVoltage":"相電壓","phaseCurrent":"相電流","powerFactor":"功率因數","formula":"公式","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"平衡三相功率的公式是什麼？","answer":"使用線間電壓和線電流，視在功率為 S = √3 × Vline × Iline。有功功率為P=S×PF。這假設一個平衡的正弦交流系統。"},{"question":"星形和三角形有什麼不同？","answer":"對於平衡星形 (Y) 連接，相電壓為線電壓除以 √3，相電流等於線電流。在三角形中，相電壓等於線電壓，相電流等於線性電流除以√3。相同線路值的總功率是相同的。"},{"question":"功率因數影響有功功率嗎？","answer":"是的。有功功率是視在功率乘以功率因數。功率因數越低，表示相同線路電壓和電流下的有功功率越少；無功功率大小根據 S × √(1 − PF²) 估算。"},{"question":"我可以將其用於不平衡負載或電氣安全設計嗎？","answer":"否。這是單相或平衡三相的理想估計。它不會分析不平衡相位、諧波、接線、設備額定值、保護、衝擊或火災風險或當地電氣規範。"}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"bg":{"copyLanguage":"bg","name":"Калкулатор за трифазна мощност","title":"Калкулатор за трифазна мощност | UsefulVerse","description":"Изчислете еднофазна или трифазна променливотокова активна, привидна и реактивна мощност. \nБезплатно, неограничено и изчислено локално във вашия браузър.","intro":"Изчислете променливотоковия ток от мрежово напрежение, мрежов ток и фактор на мощността. \nПревключвайте между еднофазни и балансирани трифазни системи и сравнете стойностите на звезда (wye) или делта фаза.","howQuestion":"Как да изчисля трифазната мощност?","howAnswer":"За балансирана трифазна система привидна мощност S = √3 × мрежово напрежение × мрежов ток, активна мощност P = S × фактор на мощността и величина на реактивната мощност Q = S × √(1 − PF²). \nПривидната монофазна мощност е V × I. Тези оценки предполагат синусоидален AC и балансиран товар за трифазен режим.","privacyQuestion":"Моите електрически стойности качени ли са?","privacyAnswer":"Не. Изчислението се изпълнява в този браузър; \nстойностите, които въвеждате, не се качват или запазват от този инструмент.","fields":{"system":"Климатична система","singlePhase":"Монофазни","threePhase":"Трифазен (балансиран)","topology":"Трифазно свързване","star":"Звезда / бяло","delta":"Делта","lineVoltage":"Мрежово напрежение","voltageUnit":"Единица за напрежение","volts":"Волта (V)","kilovolts":"Киловолта (kV)","lineCurrent":"Линеен ток","currentUnit":"Текуща единица","amperes":"Ампера (A)","kiloamperes":"Килоампери (kA)","powerFactor":"Фактор на мощността (0 до 1)","accuracyNote":"Идеална балансирана синусоидална AC оценка. \nФакторът на мощността се третира като величина; \nреактивната мощност се показва без знак. \nХармоници, фазов дисбаланс, спадове на напрежението, преходни условия, оразмеряване на проводника, защита, безопасност и съответствие с електрическия код не се моделират. \nИзползвайте измерени данни за оборудването и квалифициран инженерен преглед за реални проекти. \nСтойностите остават в този браузър."},"actions":{"calculate":"Изчислете AC мощност","reset":"Нулиране","copy":"Копиране на резултатите","example":"Опитайте 400 V, 10 A и PF 0,8","result":"Оценка на мощността"},"messages":{"calculated":"Изчислена оценка на мощността на променлив ток.","checkInputs":"Проверете напрежението, тока, фактора на мощността и поддържаните единици.","activePower":"Активна мощност (P)","apparentPower":"Привидна мощност (S)","reactivePower":"Големина на реактивната мощност (Q)","lineVoltage":"Мрежово напрежение","lineCurrent":"Линеен ток","phaseVoltage":"Фазово напрежение","phaseCurrent":"Фазов ток","powerFactor":"Фактор на мощността","formula":"Формула","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"Каква е формулата за балансирана трифазна мощност?","answer":"Използвайки напрежение между линия и мрежов ток, привидната мощност е S = √3 × Vline × Iline. \nАктивната мощност е P = S × PF. \nТова предполага балансирана синусоидална AC система."},{"question":"Каква е разликата между звезда и делта?","answer":"За балансирана връзка звезда (звезда), фазовото напрежение е линейното напрежение, разделено на √3, а фазовият ток е равен на линейния ток. \nВ делта фазовото напрежение е равно на линейното напрежение, а фазовият ток е линейният ток, разделен на √3. \nОбщата мощност за същите стойности на линията е една и съща."},{"question":"Факторът на мощността влияе ли на активната мощност?","answer":"Да. \nАктивната мощност е привидната мощност, умножена по фактора на мощността. \nПо-нисък фактор на мощността означава по-малка активна мощност за същото мрежово напрежение и ток; \nвеличината на реактивната мощност се изчислява от S × √(1 − PF²)."},{"question":"Мога ли да използвам това за небалансирани товари или дизайн за електрическа безопасност?","answer":"Не. Това е идеализирана оценка за еднофазна или балансирана трифазна. \nТой не анализира небалансирани фази, хармоници, окабеляване, рейтинги на оборудването, защита, риск от удар или пожар или местни електрически кодове."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"ca":{"copyLanguage":"ca","name":"Calculadora de potència trifàsica","title":"Calculadora de potència trifàsica | UsefulVerse","description":"Calcula la potència activa, aparent i reactiva de CA monofàsica o trifàsica. \nGratuït, il·limitat i calculat localment al vostre navegador.","intro":"Estimar la potència de CA a partir de la tensió de línia, el corrent de línia i el factor de potència. \nCanvia entre sistemes monofàsics i trifàsics equilibrats i compara els valors de la fase estrella (estrella) o delta.","howQuestion":"Com calculo la potència trifàsica?","howAnswer":"Per a un sistema trifàsic equilibrat, potència aparent S = √3 × tensió de línia × corrent de línia, potència activa P = S × factor de potència i magnitud de potència reactiva Q = S × √(1 − PF²). \nLa potència aparent monofàsica és V × I. Aquestes estimacions suposen CA sinusoïdal i una càrrega equilibrada per al mode trifàsic.","privacyQuestion":"S'han penjat els meus valors elèctrics?","privacyAnswer":"No. El càlcul s'executa en aquest navegador; \nAquesta eina no carrega ni desa els valors que introduïu.","fields":{"system":"Sistema de CA","singlePhase":"Monofàsica","threePhase":"Trifàsic (equilibrat)","topology":"Connexió trifàsica","star":"Estrella / estrella","delta":"Delta","lineVoltage":"Tensió de línia","voltageUnit":"Unitat de tensió","volts":"volts (V)","kilovolts":"quilovolts (kV)","lineCurrent":"Corrent de línia","currentUnit":"Unitat actual","amperes":"amperes (A)","kiloamperes":"quiloamperes (kA)","powerFactor":"Factor de potència (0 a 1)","accuracyNote":"Estimació de CA sinusoïdal equilibrada ideal. \nEl factor de potència es tracta com una magnitud; \nla potència reactiva es mostra sense signar. \nEls harmònics, el desequilibri de fase, les caigudes de tensió, les condicions transitòries, la mida del conductor, la protecció, la seguretat i el compliment del codi elèctric no es modelen. \nUtilitzeu dades d'equips mesurats i revisió d'enginyeria qualificada per a dissenys reals. \nEls valors es mantenen en aquest navegador."},"actions":{"calculate":"Calcula la potència CA","reset":"Restablir","copy":"Copia els resultats","example":"Prova 400 V, 10 A i PF 0,8","result":"Potència estimada"},"messages":{"calculated":"Estimació de la potència CA calculada.","checkInputs":"Comproveu la tensió, el corrent, el factor de potència i les unitats admeses.","activePower":"Potència activa (P)","apparentPower":"Potència aparent (S)","reactivePower":"Magnitud de la potència reactiva (Q)","lineVoltage":"Tensió de línia","lineCurrent":"Corrent de línia","phaseVoltage":"Tensió de fase","phaseCurrent":"Corrent de fase","powerFactor":"Factor de potència","formula":"Fórmula","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"What is the formula for balanced three-phase power?","answer":"Using line-to-line voltage and line current, apparent power is S = √3 × Vline × Iline. \nLa potència activa és P = S × PF. \nAixò suposa un sistema de CA sinusoïdal equilibrat."},{"question":"What is the difference between star and delta?","answer":"For a balanced star (wye) connection, phase voltage is line voltage divided by √3 and phase current equals line current. \nIn delta, phase voltage equals line voltage and phase current is line current divided by √3. \nThe total power for the same line values is the same."},{"question":"Does power factor affect active power?","answer":"Sí. \nActive power is apparent power multiplied by power factor. \nLower power factor means less active power for the same line voltage and current; \nreactive-power magnitude is estimated from S × √(1 − PF²)."},{"question":"Can I use this for unbalanced loads or electrical safety design?","answer":"No. This is an idealized estimate for single phase or balanced three phase. \nIt does not analyze unbalanced phases, harmonics, wiring, equipment ratings, protection, shock or fire risk, or local electrical codes."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"nl":{"copyLanguage":"nl","name":"Driefasige stroomcalculator","title":"Driefasige stroomcalculator | UsefulVerse","description":"Bereken het actief, schijnbaar en blindvermogen van een- of driefasig AC. \nGratis, onbeperkt en lokaal berekend in uw browser.","intro":"Schat het wisselstroomvermogen op basis van lijnspanning, lijnstroom en arbeidsfactor. \nSchakel tussen eenfasige en gebalanceerde driefasige systemen en vergelijk ster- (Y-) of delta-fasewaarden.","howQuestion":"Hoe bereken ik driefasig vermogen?","howAnswer":"Voor een gebalanceerd driefasig systeem, schijnbaar vermogen S = √3 × lijnspanning × lijnstroom, actief vermogen P = S × arbeidsfactor, en grootte van het blindvermogen Q = S × √(1 − PF²). \nEenfasig schijnbaar vermogen is V × I. Deze schattingen gaan uit van sinusoïdale wisselstroom en een gebalanceerde belasting voor de driefasige modus.","privacyQuestion":"Worden mijn elektrische waarden geüpload?","privacyAnswer":"Nee. De berekening wordt in deze browser uitgevoerd; \nwaarden die u invoert, worden niet geüpload of opgeslagen door deze tool.","fields":{"system":"AC-systeem","singlePhase":"Eenfasig","threePhase":"Driefasig (gebalanceerd)","topology":"Driefasige aansluiting","star":"Ster / y","delta":"Delta","lineVoltage":"Lijnspanning","voltageUnit":"Spanningseenheid","volts":"Volt (V)","kilovolts":"Kilovolt (kV)","lineCurrent":"Lijnstroom","currentUnit":"Huidige eenheid","amperes":"Ampère (A)","kiloamperes":"Kiloampère (kA)","powerFactor":"Vermogensfactor (0 tot 1)","accuracyNote":"Ideale gebalanceerde sinusoïdale AC-schatting. \nDe arbeidsfactor wordt behandeld als een grootheid; \nreactief vermogen wordt zonder teken weergegeven. \nHarmonischen, fase-onbalans, spanningsdalingen, transiënte omstandigheden, geleiderafmetingen, bescherming, veiligheid en naleving van de elektrische regelgeving zijn niet gemodelleerd. \nGebruik gemeten apparatuurgegevens en gekwalificeerde technische beoordelingen voor echte ontwerpen. \nWaarden blijven in deze browser."},"actions":{"calculate":"Bereken het wisselstroomvermogen","reset":"Opnieuw instellen","copy":"Resultaten kopiëren","example":"Probeer 400 V, 10 A en PF 0,8","result":"Vermogensschatting"},"messages":{"calculated":"Schatting wisselstroomvermogen berekend.","checkInputs":"Controleer spanning, stroom, arbeidsfactor en ondersteunde eenheden.","activePower":"Actief vermogen (P)","apparentPower":"Schijnbaar vermogen (S)","reactivePower":"Reactief vermogen (Q)","lineVoltage":"Lijnspanning","lineCurrent":"Lijnstroom","phaseVoltage":"Fasespanning","phaseCurrent":"Fasestroom","powerFactor":"Vermogensfactor","formula":"Formule","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"Wat is de formule voor gebalanceerde driefasige stroom?","answer":"Bij gebruik van lijn-tot-lijnspanning en lijnstroom is het schijnbaar vermogen S = √3 × Vnet × Inet. \nActief vermogen is P = S × PF. \nHierbij wordt uitgegaan van een gebalanceerd sinusoïdaal wisselstroomsysteem."},{"question":"Wat is het verschil tussen ster en delta?","answer":"Voor een gebalanceerde sterverbinding (Y-verbinding) is de fasespanning de lijnspanning gedeeld door √3 en is de fasestroom gelijk aan de lijnstroom. \nIn delta is de fasespanning gelijk aan de lijnspanning en is de fasestroom de lijnstroom gedeeld door √3. \nHet totale vermogen voor dezelfde lijnwaarden is hetzelfde."},{"question":"Heeft de arbeidsfactor invloed op het actieve vermogen?","answer":"Ja. \nActief vermogen is schijnbaar vermogen vermenigvuldigd met de arbeidsfactor. \nEen lagere arbeidsfactor betekent minder actief vermogen bij dezelfde lijnspanning en -stroom; \nDe omvang van het reactieve vermogen wordt geschat op basis van S × √(1 − PF²)."},{"question":"Kan ik dit gebruiken voor ongebalanceerde belastingen of elektrische veiligheidsontwerpen?","answer":"Nee. Dit is een geïdealiseerde schatting voor enkelfasig of gebalanceerd driefasig. \nHet analyseert geen ongebalanceerde fasen, harmonischen, bedrading, apparatuurclassificaties, bescherming, schok- of brandrisico, of lokale elektrische codes."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"el":{"copyLanguage":"el","name":"Τριφασικός Υπολογιστής ρεύματος","title":"Τριφασικός Υπολογιστής ρεύματος | UsefulVerse","description":"Υπολογισμός μονοφασικού ή τριφασικού AC ενεργού, φαινομένου και άεργου ισχύος. \nΔωρεάν, απεριόριστα και υπολογίζεται τοπικά στο πρόγραμμα περιήγησής σας.","intro":"Υπολογίστε την ισχύ AC από την τάση γραμμής, το ρεύμα γραμμής και τον συντελεστή ισχύος. \nΚάντε εναλλαγή μεταξύ μονοφασικών και ισορροπημένων τριφασικών συστημάτων και συγκρίνετε τιμές αστεριού (wye) ή δέλτα φάσης.","howQuestion":"Πώς μπορώ να υπολογίσω την τριφασική ισχύ;","howAnswer":"Για ένα ισορροπημένο τριφασικό σύστημα, φαινόμενη ισχύς S = √3 × τάση γραμμής × ρεύμα γραμμής, ενεργή ισχύς P = S × συντελεστής ισχύος και μέγεθος άεργου ισχύος Q = S × √(1 − PF²). \nΗ μονοφασική φαινόμενη ισχύς είναι V × I. Αυτές οι εκτιμήσεις υποθέτουν ημιτονοειδές εναλλασσόμενο ρεύμα και ισορροπημένο φορτίο για τριφασική λειτουργία.","privacyQuestion":"Έχουν μεταφορτωθεί οι ηλεκτρικές μου τιμές;","privacyAnswer":"Όχι. Ο υπολογισμός εκτελείται σε αυτό το πρόγραμμα περιήγησης. \nΟι τιμές που εισάγετε δεν μεταφορτώνονται ούτε αποθηκεύονται από αυτό το εργαλείο.","fields":{"system":"Σύστημα AC","singlePhase":"Μονοφασικό","threePhase":"Τριφασικό (ισορροπημένο)","topology":"Τριφασική σύνδεση","star":"Star / wye","delta":"Δέλτα","lineVoltage":"Τάση γραμμής","voltageUnit":"Μονάδα τάσης","volts":"Volt (V)","kilovolts":"Kilovolt (kV)","lineCurrent":"Ρεύμα γραμμής","currentUnit":"Τρέχουσα μονάδα","amperes":"Αμπέρ (Α)","kiloamperes":"Κιλοαμπέρ (kA)","powerFactor":"Συντελεστής ισχύος (0 έως 1)","accuracyNote":"Ιδανική ισορροπημένη ημιτονοειδής εκτίμηση AC. \nΟ συντελεστής ισχύος αντιμετωπίζεται ως μέγεθος. \nΗ άεργος ισχύς εμφανίζεται ανυπόγραφη. \nΟι αρμονικές, η ανισορροπία φάσης, οι πτώσεις τάσης, οι μεταβατικές συνθήκες, το μέγεθος του αγωγού, η προστασία, η ασφάλεια και η συμμόρφωση με τον ηλεκτρικό κώδικα δεν μοντελοποιούνται. \nΧρησιμοποιήστε δεδομένα μετρήσεων εξοπλισμού και πιστοποιημένη αναθεώρηση μηχανικής για πραγματικά σχέδια. \nΟι τιμές παραμένουν σε αυτό το πρόγραμμα περιήγησης."},"actions":{"calculate":"Υπολογισμός ισχύος AC","reset":"Επαναφορά","copy":"Αντιγραφή αποτελεσμάτων","example":"Δοκιμάστε 400 V, 10 A και PF 0,8","result":"Εκτίμηση ισχύος"},"messages":{"calculated":"Υπολογισμός ισχύος AC.","checkInputs":"Ελέγξτε την τάση, το ρεύμα, τον συντελεστή ισχύος και τις υποστηριζόμενες μονάδες.","activePower":"Ενεργή ισχύς (P)","apparentPower":"Φαινόμενη ισχύς (S)","reactivePower":"Μέγεθος άεργου ισχύος (Q)","lineVoltage":"Τάση γραμμής","lineCurrent":"Ρεύμα γραμμής","phaseVoltage":"Τάση φάσης","phaseCurrent":"Ρεύμα φάσης","powerFactor":"Συντελεστής ισχύος","formula":"Φόρμουλα","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"Ποιος είναι ο τύπος για ισορροπημένη τριφασική ισχύ;","answer":"Χρησιμοποιώντας τάση γραμμής προς γραμμή και ρεύμα γραμμής, η φαινόμενη ισχύς είναι S = √3 × Vline × Iline. \nΗ ενεργός ισχύς είναι P = S × PF. \nΑυτό προϋποθέτει ένα ισορροπημένο ημιτονοειδές σύστημα AC."},{"question":"Ποια είναι η διαφορά μεταξύ αστεριού και δέλτα;","answer":"Για μια ισορροπημένη σύνδεση αστεριού (wye), η τάση φάσης είναι η τάση γραμμής διαιρούμενη με √3 και το ρεύμα φάσης ισούται με το ρεύμα γραμμής. \nΣτο δέλτα, η τάση φάσης ισούται με την τάση γραμμής και το ρεύμα φάσης είναι το ρεύμα γραμμής διαιρούμενο με √3. \nΗ συνολική ισχύς για τις ίδιες τιμές γραμμής είναι η ίδια."},{"question":"Επηρεάζει ο συντελεστής ισχύος την ενεργή ισχύ;","answer":"Ναι. \nΗ ενεργός ισχύς είναι η φαινόμενη ισχύς πολλαπλασιασμένη με τον συντελεστή ισχύος. \nΧαμηλότερος συντελεστής ισχύος σημαίνει λιγότερη ενεργή ισχύς για την ίδια τάση και ρεύμα γραμμής. \nΤο μέγεθος της άεργου ισχύος υπολογίζεται από S × √(1 − PF²)."},{"question":"Μπορώ να το χρησιμοποιήσω για μη ισορροπημένα φορτία ή σχεδιασμό ηλεκτρικής ασφάλειας;","answer":"Όχι. Αυτή είναι μια εξιδανικευμένη εκτίμηση για μονοφασική ή ισορροπημένη τριφασική. \nΔεν αναλύει μη ισορροπημένες φάσεις, αρμονικές, καλωδιώσεις, ονομασίες εξοπλισμού, προστασία, κίνδυνο ηλεκτροπληξίας ή πυρκαγιάς ή τοπικούς ηλεκτρικούς κώδικες."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"ms":{"copyLanguage":"ms","name":"Kalkulator Kuasa Tiga Fasa","title":"Kalkulator Kuasa Tiga Fasa | UsefulVerse","description":"Kira satu atau tiga fasa AC aktif, kuasa ketara dan reaktif. \nPercuma, tidak terhad dan dikira secara tempatan dalam penyemak imbas anda.","intro":"Anggarkan kuasa AC daripada voltan talian, arus talian dan faktor kuasa. \nBeralih antara sistem tiga fasa fasa tunggal dan seimbang, dan bandingkan nilai fasa bintang (wye) atau delta.","howQuestion":"Bagaimanakah cara mengira kuasa tiga fasa?","howAnswer":"Untuk sistem tiga fasa yang seimbang, kuasa ketara S = √3 × voltan talian × arus talian, kuasa aktif P = S × faktor kuasa, dan magnitud kuasa reaktif Q = S × √(1 − PF²). \nKuasa ketara fasa tunggal ialah V × I. Anggaran ini menganggap AC sinusoidal dan beban seimbang untuk mod tiga fasa.","privacyQuestion":"Adakah nilai elektrik saya dimuat naik?","privacyAnswer":"Tidak. Pengiraan dijalankan dalam pelayar ini; \nnilai yang anda masukkan tidak dimuat naik atau disimpan oleh alat ini.","fields":{"system":"Sistem AC","singlePhase":"Fasa tunggal","threePhase":"Tiga fasa (seimbang)","topology":"Sambungan tiga fasa","star":"Bintang / wye","delta":"Delta","lineVoltage":"Voltan talian","voltageUnit":"Unit voltan","volts":"Volt (V)","kilovolts":"Kilovolt (kV)","lineCurrent":"Arus talian","currentUnit":"Unit semasa","amperes":"Amperes (A)","kiloamperes":"Kiloamperes (kA)","powerFactor":"Faktor kuasa (0 hingga 1)","accuracyNote":"Anggaran AC sinusoidal seimbang yang ideal. \nFaktor kuasa dianggap sebagai magnitud; \nkuasa reaktif ditunjukkan tidak ditandatangani. \nHarmonik, ketidakseimbangan fasa, penurunan voltan, keadaan sementara, saiz konduktor, perlindungan, keselamatan dan pematuhan kod elektrik tidak dimodelkan. \nGunakan data peralatan yang diukur dan semakan kejuruteraan yang berkelayakan untuk reka bentuk sebenar. \nNilai kekal dalam penyemak imbas ini."},"actions":{"calculate":"Kira kuasa AC","reset":"Tetapkan semula","copy":"Salin keputusan","example":"Cuba 400 V, 10 A dan PF 0.8","result":"Anggaran kuasa"},"messages":{"calculated":"Anggaran kuasa AC dikira.","checkInputs":"Periksa voltan, arus, faktor kuasa dan unit yang disokong.","activePower":"Kuasa aktif (P)","apparentPower":"Kuasa ketara (S)","reactivePower":"Magnitud kuasa reaktif (Q)","lineVoltage":"Voltan talian","lineCurrent":"Arus talian","phaseVoltage":"Voltan fasa","phaseCurrent":"Fasa semasa","powerFactor":"Faktor kuasa","formula":"Formula","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"Apakah formula bagi kuasa tiga fasa seimbang?","answer":"Menggunakan voltan talian ke talian dan arus talian, kuasa ketara ialah S = √3 × Vline × Iline. \nKuasa aktif ialah P = S × PF. \nIni menganggap sistem AC sinusoidal seimbang."},{"question":"Apakah perbezaan antara bintang dan delta?","answer":"Untuk sambungan bintang (wye) seimbang, voltan fasa ialah voltan talian dibahagikan dengan √3 dan arus fasa sama dengan arus talian. \nDalam delta, voltan fasa sama dengan voltan talian dan arus fasa ialah arus talian dibahagikan dengan √3. \nJumlah kuasa untuk nilai baris yang sama adalah sama."},{"question":"Adakah faktor kuasa mempengaruhi kuasa aktif?","answer":"Ya. \nKuasa aktif ialah kuasa ketara didarab dengan faktor kuasa. \nFaktor kuasa yang lebih rendah bermakna kuasa kurang aktif untuk voltan dan arus talian yang sama; \nmagnitud kuasa reaktif dianggarkan daripada S × √(1 − PF²)."},{"question":"Bolehkah saya menggunakan ini untuk beban tidak seimbang atau reka bentuk keselamatan elektrik?","answer":"Tidak. Ini adalah anggaran ideal untuk fasa tunggal atau tiga fasa seimbang. \nIa tidak menganalisis fasa tidak seimbang, harmonik, pendawaian, penilaian peralatan, perlindungan, kejutan atau risiko kebakaran, atau kod elektrik tempatan."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"pl":{"copyLanguage":"pl","name":"Trójfazowy kalkulator mocy","title":"Trójfazowy kalkulator mocy | UsefulVerse","description":"Obliczanie mocy czynnej, pozornej i biernej prądu przemiennego jednofazowego lub trójfazowego. \nBezpłatne, nieograniczone i obliczane lokalnie w Twojej...","intro":"Oszacuj moc prądu przemiennego na podstawie napięcia sieciowego, prądu sieciowego i współczynnika mocy. \nPrzełączaj się między układami jednofazowymi i zrównoważonymi układami trójfazowymi i porównuj wartości fazy gwiazdy (gwiazdy) lub trójkąta.","howQuestion":"Jak obliczyć moc trójfazową?","howAnswer":"W przypadku zrównoważonego układu trójfazowego moc pozorna S = √3 × napięcie sieci × prąd sieci, moc czynna P = S × współczynnik mocy i wielkość mocy biernej Q = S × √(1 – PF²). \nMoc pozorna jednofazowej wynosi V × I. Szacunki te zakładają sinusoidalny prąd przemienny i zrównoważone obciążenie dla trybu trójfazowego.","privacyQuestion":"Czy moje wartości elektryczne zostały przesłane?","privacyAnswer":"Nie. Kalkulacja przebiega w tej przeglądarce; \nwprowadzone wartości nie są przesyłane ani zapisywane przez to narzędzie.","fields":{"system":"Układ klimatyzacji","singlePhase":"Jednofazowy","threePhase":"Trójfazowy (symetryczny)","topology":"Podłączenie trójfazowe","star":"Gwiazda / gwiazda","delta":"Delta","lineVoltage":"Napięcie sieciowe","voltageUnit":"Jednostka napięcia","volts":"V (V)","kilovolts":"Kilowoltów (kV)","lineCurrent":"Prąd liniowy","currentUnit":"Aktualna jednostka","amperes":"Ampery (A)","kiloamperes":"Kiloamperów (kA)","powerFactor":"Współczynnik mocy (0 do 1)","accuracyNote":"Idealnie zrównoważone sinusoidalne oszacowanie prądu przemiennego. \nWspółczynnik mocy traktowany jest jako wielkość; \nmoc bierna jest pokazana bez znaku. \nHarmoniczne, asymetria faz, spadki napięcia, warunki przejściowe, dobór przewodów, ochrona, bezpieczeństwo i zgodność z przepisami elektrycznymi nie są modelowane. \nWykorzystaj dane zmierzonego sprzętu i wykwalifikowany przegląd inżynieryjny do rzeczywistych projektów. \nWartości pozostają w tej przeglądarce."},"actions":{"calculate":"Oblicz moc prądu przemiennego","reset":"Resetuj","copy":"Skopiuj wyniki","example":"Wypróbuj 400 V, 10 A i PF 0,8","result":"Oszacowanie mocy"},"messages":{"calculated":"Obliczono szacunkową moc prądu przemiennego.","checkInputs":"Sprawdź napięcie, prąd, współczynnik mocy i obsługiwane jednostki.","activePower":"Moc czynna (P)","apparentPower":"Moc pozorna (S)","reactivePower":"Wielkość mocy biernej (Q)","lineVoltage":"Napięcie sieciowe","lineCurrent":"Prąd liniowy","phaseVoltage":"Napięcie fazowe","phaseCurrent":"Prąd fazowy","powerFactor":"Współczynnik mocy","formula":"Formuła","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"Jaki jest wzór na zrównoważoną moc trójfazową?","answer":"Przy zastosowaniu napięcia międzyfazowego i prądu liniowego moc pozorna wynosi S = √3 × Vline × Iline. \nMoc czynna wynosi P = S × PF. \nZakłada to zrównoważony sinusoidalny system prądu przemiennego."},{"question":"Jaka jest różnica między gwiazdą a trójkątem?","answer":"W przypadku zbalansowanego połączenia w gwiazdę (gwiazdę) napięcie fazowe to napięcie sieciowe podzielone przez √3, a prąd fazowy jest równy prądowi sieciowemu. \nW delcie napięcie fazowe jest równe napięciu sieciowemu, a prąd fazowy jest prądem sieciowym podzielonym przez √3. \nCałkowita moc dla tych samych wartości linii jest taka sama."},{"question":"Czy współczynnik mocy wpływa na moc czynną?","answer":"Tak. \nMoc czynna to moc pozorna pomnożona przez współczynnik mocy. \nNiższy współczynnik mocy oznacza mniejszą moc czynną przy tym samym napięciu i prądzie sieciowym; \nwielkość mocy biernej szacuje się na podstawie S × √(1 - PF²)."},{"question":"Czy mogę tego użyć do obciążenia niezrównoważonego lub do projektowania bezpieczeństwa elektrycznego?","answer":"Nie. Jest to wyidealizowany szacunek dla jednej fazy lub zrównoważonej trójfazowej. \nNie analizuje niezrównoważonych faz, harmonicznych, okablowania, parametrów sprzętu, zabezpieczeń, ryzyka porażenia prądem lub pożarem, ani lokalnych przepisów elektrycznych."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"sv":{"copyLanguage":"sv","name":"Trefasig effektkalkylator","title":"Trefasig effektkalkylator | UsefulVerse","description":"Beräkna en- eller trefas AC aktiv, skenbar och reaktiv effekt. \nGratis, obegränsat och beräknat lokalt i din webbläsare.","intro":"Beräkna växelström från nätspänning, nätström och effektfaktor. \nVäxla mellan enfasiga och balanserade trefassystem och jämför stjärn- (wye) eller deltafasvärden.","howQuestion":"Hur beräknar jag trefaseffekt?","howAnswer":"För ett balanserat trefassystem, skenbar effekt S = √3 × linjespänning × linjeström, aktiv effekt P = S × effektfaktor och reaktiv effektstorlek Q = S × √(1 − PF²). \nEnfas skenbar effekt är V × I. Dessa uppskattningar antar sinusformad AC och en balanserad belastning för trefasläge.","privacyQuestion":"Är mina elektriska värden uppladdade?","privacyAnswer":"Nej. Beräkningen körs i den här webbläsaren; \nvärden du anger laddas inte upp eller sparas av detta verktyg.","fields":{"system":"AC-system","singlePhase":"Enfas","threePhase":"Trefas (balanserad)","topology":"Trefasanslutning","star":"Stjärna / wye","delta":"Delta","lineVoltage":"Linjespänning","voltageUnit":"Spänningsenhet","volts":"Volt (V)","kilovolts":"Kilovolt (kV)","lineCurrent":"Linjeström","currentUnit":"Aktuell enhet","amperes":"Ampere (A)","kiloamperes":"Kiloampere (kA)","powerFactor":"Effektfaktor (0 till 1)","accuracyNote":"Idealisk balanserad sinusformad AC-uppskattning. \nEffektfaktor behandlas som en magnitud; \nreaktiv effekt visas osignerad. \nÖvertoner, fasobalans, spänningsfall, transienta förhållanden, ledarstorlek, skydd, säkerhet och överensstämmelse med elektriska koder modelleras inte. \nAnvänd uppmätta utrustningsdata och kvalificerad ingenjörsgranskning för riktiga konstruktioner. \nVärden stannar i den här webbläsaren."},"actions":{"calculate":"Beräkna växelström","reset":"Återställ","copy":"Kopiera resultat","example":"Prova 400 V, 10 A och PF 0,8","result":"Effektuppskattning"},"messages":{"calculated":"Beräknad växelströmseffekt.","checkInputs":"Kontrollera spänning, ström, effektfaktor och enheter som stöds.","activePower":"Aktiv effekt (P)","apparentPower":"Skenbar kraft (S)","reactivePower":"Reaktiv effektstorlek (Q)","lineVoltage":"Linjespänning","lineCurrent":"Linjeström","phaseVoltage":"Fasspänning","phaseCurrent":"Fasström","powerFactor":"Effektfaktor","formula":"Formel","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"Vad är formeln för balanserad trefaseffekt?","answer":"Med användning av linje-till-linje-spänning och linjeström är den skenbara effekten S = √3 × Vline × Iline. \nAktiv effekt är P = S × PF. \nDetta förutsätter ett balanserat sinusformigt AC-system."},{"question":"Vad är skillnaden mellan stjärna och delta?","answer":"För en balanserad stjärnanslutning (wye) är fasspänning linjespänning dividerad med √3 och fasström är lika med linjeström. \nI delta är fasspänning lika med linjespänning och fasström är linjeström dividerat med √3. \nDen totala effekten för samma linjevärden är densamma."},{"question":"Påverkar effektfaktor aktiv effekt?","answer":"Ja. \nAktiv effekt är skenbar effekt multiplicerad med effektfaktor. \nLägre effektfaktor betyder mindre aktiv effekt för samma linjespänning och ström; \nStorleken på reaktiv effekt uppskattas från S × √(1 − PF²)."},{"question":"Kan jag använda detta för obalanserade belastningar eller elektrisk säkerhetsdesign?","answer":"Nej. Detta är en idealiserad uppskattning för enfas eller balanserad trefas. \nDen analyserar inte obalanserade faser, övertoner, ledningar, utrustningsklassificeringar, skydd, stöt- eller brandrisk eller lokala elektriska koder."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"th":{"copyLanguage":"th","name":"เครื่องคำนวณกำลังสามเฟส","title":"เครื่องคำนวณกำลังสามเฟส | UsefulVerse","description":"คำนวณพลังงานไฟฟ้ากระแสสลับ ปรากฏ และปฏิกิริยาไฟฟ้ากระแสสลับเฟสเดียวหรือสามเฟส \nฟรี ไม่จำกัด และคำนวณในเบราว์เซอร์ของคุณ","intro":"ประมาณกำลังไฟ AC จากแรงดันไฟหลัก กระแสไฟหลัก และตัวประกอบกำลัง \nสลับระหว่างระบบเฟสเดียวและระบบสามเฟสที่สมดุล และเปรียบเทียบค่าเฟสสตาร์ (ไวย์) หรือเดลต้า","howQuestion":"จะคำนวณไฟสามเฟสได้อย่างไร?","howAnswer":"สำหรับระบบสามเฟสที่สมดุล กำลังไฟฟ้าปรากฏ S = √3 × แรงดันไฟฟ้าของเส้น × กระแสของเส้น กำลังไฟฟ้าที่ใช้งาน P = S × ตัวประกอบกำลัง และขนาดกำลังไฟฟ้ารีแอกทีฟ Q = S × √(1 − PF²) \nกำลังไฟฟ้าปรากฏเฟสเดียวคือ V × I การประมาณเหล่านี้ถือว่า AC แบบไซน์ซอยด์และโหลดที่สมดุลสำหรับโหมดสามเฟส","privacyQuestion":"ค่าไฟฟ้าของฉันถูกอัปโหลดหรือไม่","privacyAnswer":"ไม่ การคำนวณทำงานในเบราว์เซอร์นี้ \nค่าที่คุณป้อนไม่ได้ถูกอัพโหลดหรือบันทึกโดยเครื่องมือนี้","fields":{"system":"ระบบไฟฟ้ากระแสสลับ","singlePhase":"เฟสเดียว","threePhase":"สามเฟส (บาลานซ์)","topology":"การเชื่อมต่อสามเฟส","star":"สตาร์/วาย","delta":"เดลต้า","lineVoltage":"แรงดันไฟฟ้าของสาย","voltageUnit":"หน่วยแรงดันไฟฟ้า","volts":"โวลต์ (V)","kilovolts":"กิโลโวลต์ (kV)","lineCurrent":"สายกระแส","currentUnit":"หน่วยปัจจุบัน","amperes":"แอมแปร์ (A)","kiloamperes":"กิโลแอมแปร์ (kA)","powerFactor":"ตัวประกอบกำลัง (0 ถึง 1)","accuracyNote":"ค่าประมาณ AC ไซน์ซอยด์ที่สมดุลในอุดมคติ \nตัวประกอบกำลังถือเป็นขนาด \nกำลังไฟฟ้ารีแอกทีฟจะแสดงขึ้นโดยไม่ได้ลงนาม \nฮาร์มอนิก ความไม่สมดุลของเฟส แรงดันไฟฟ้าตก สภาวะชั่วคราว ขนาดตัวนำ การป้องกัน ความปลอดภัย และการปฏิบัติตามรหัสทางไฟฟ้าไม่ได้เป็นแบบจำลอง \nใช้ข้อมูลอุปกรณ์ที่วัดได้และการทบทวนทางวิศวกรรมที่ผ่านการรับรองสำหรับการออกแบบจริง \nค่าจะยังคงอยู่ในเบราว์เซอร์นี้"},"actions":{"calculate":"คำนวณไฟ AC","reset":"รีเซ็ต","copy":"คัดลอกผลลัพธ์","example":"ลอง 400 V, 10 A และ PF 0.8","result":"การประมาณกำลัง"},"messages":{"calculated":"คำนวณค่าไฟ AC แล้ว","checkInputs":"ตรวจสอบแรงดันไฟฟ้า กระแสไฟฟ้า ตัวประกอบกำลัง และหน่วยที่รองรับ","activePower":"พลังงานที่ใช้งานอยู่ (P)","apparentPower":"พลังปรากฏ (S)","reactivePower":"ขนาดพลังงานปฏิกิริยา (Q)","lineVoltage":"แรงดันไฟฟ้าของสาย","lineCurrent":"สายกระแส","phaseVoltage":"แรงดันเฟส","phaseCurrent":"กระแสเฟส","powerFactor":"ตัวประกอบกำลัง","formula":"สูตร","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"สูตรสมดุลไฟฟ้า 3 เฟส คืออะไร?","answer":"การใช้แรงดันไฟฟ้าแบบเส้นต่อเส้นและกระแสแบบเส้น กำลังไฟฟ้าที่ปรากฏคือ S = √3 × Vline × Iline \nพลังงานที่ใช้งานคือ P = S × PF \nสิ่งนี้ถือว่าระบบ AC แบบไซน์ซอยด์ที่สมดุล"},{"question":"สตาร์กับเดลต้าต่างกันอย่างไร?","answer":"สำหรับการเชื่อมต่อแบบดาวที่สมดุล (ไวย์) แรงดันเฟสคือแรงดันไฟหลักหารด้วย √3 และกระแสเฟสเท่ากับกระแสไฟหลัก \nในเดลต้า แรงดันเฟสเท่ากับแรงดันไฟฟ้าของเส้น และกระแสเฟสคือกระแสของเส้นหารด้วย √3 \nกำลังรวมสำหรับค่าเส้นเดียวกันจะเท่ากัน"},{"question":"ตัวประกอบกำลังส่งผลต่อพลังงานที่ใช้งานอยู่หรือไม่?","answer":"ค่ะ \nกำลังไฟฟ้าที่ใช้งานอยู่คือกำลังไฟฟ้าที่ชัดเจนคูณด้วยตัวประกอบกำลัง \nตัวประกอบกำลังที่ต่ำกว่าหมายถึงกำลังงานที่ใช้งานน้อยลงสำหรับแรงดันและกระแสในสายเดียวกัน \nขนาดพลังงานปฏิกิริยาประมาณจาก S × √ (1 - PF²)"},{"question":"ฉันสามารถใช้สิ่งนี้กับโหลดที่ไม่สมดุลหรือการออกแบบเพื่อความปลอดภัยทางไฟฟ้าได้หรือไม่","answer":"ไม่ นี่เป็นค่าประมาณในอุดมคติสำหรับเฟสเดียวหรือสามเฟสที่สมดุล \nโดยจะไม่วิเคราะห์เฟสที่ไม่สมดุล ฮาร์โมนิค สายไฟ พิกัดอุปกรณ์ การป้องกัน ความเสี่ยงจากไฟฟ้าช็อตหรือไฟไหม้ หรือรหัสไฟฟ้าในพื้นที่\n\nอนุมัติแล้ว"}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"uk":{"copyLanguage":"uk","name":"Трифазний калькулятор потужності","title":"Трифазний калькулятор потужності | UsefulVerse","description":"Розрахунок активної, повної та реактивної потужності одно- або трифазного змінного струму. \nБезкоштовно, без обмежень і розраховується локально у вашому...","intro":"Оцініть потужність змінного струму на основі напруги в мережі, струму в мережі та коефіцієнта потужності. \nПеремикайтеся між однофазною та збалансованою трифазною системами та порівнюйте значення фази зірка (зірка) або дельта.","howQuestion":"Як розрахувати трифазну потужність?","howAnswer":"Для збалансованої трифазної системи повна потужність S = √3 × лінійна напруга × лінійний струм, активна потужність P = S × коефіцієнт потужності та величина реактивної потужності Q = S × √(1 − PF²). \nПовна однофазна потужність V × I. Ці оцінки передбачають синусоїдальний змінний струм і збалансоване навантаження для трифазного режиму.","privacyQuestion":"Чи завантажено мої електричні значення?","privacyAnswer":"Ні. Розрахунок виконується в цьому браузері; \nзначення, які ви вводите, не завантажуються та не зберігаються цим інструментом.","fields":{"system":"Система кондиціонування","singlePhase":"Однофазний","threePhase":"Трифазний (симетричний)","topology":"Трифазне підключення","star":"Зірка / сітка","delta":"Дельта","lineVoltage":"Напруга мережі","voltageUnit":"Одиниця напруги","volts":"Вольт (В)","kilovolts":"Кіловольт (кВ)","lineCurrent":"Лінійний струм","currentUnit":"Од","amperes":"Ампер (A)","kiloamperes":"Кілоампер (кА)","powerFactor":"Коефіцієнт потужності (від 0 до 1)","accuracyNote":"Оцінка ідеального збалансованого синусоїдального змінного струму. \nКоефіцієнт потужності розглядається як величина; \nреактивна потужність показана без знака. \nГармоніки, дисбаланс фаз, падіння напруги, перехідні процеси, розмір провідника, захист, безпека та відповідність електричним нормам не моделюються. \nВикористовуйте дані вимірювань обладнання та кваліфікований інженерний огляд для реальних проектів. \nЗначення залишаються в цьому браузері."},"actions":{"calculate":"Обчисліть потужність змінного струму","reset":"Скинути","copy":"Копіювати результати","example":"Спробуйте 400 В, 10 A та PF 0,8","result":"Оцінка потужності"},"messages":{"calculated":"Розраховано оцінку потужності змінного струму.","checkInputs":"Перевірте напругу, струм, коефіцієнт потужності та підтримувані одиниці.","activePower":"Активна потужність (P)","apparentPower":"Повна потужність (S)","reactivePower":"Величина реактивної потужності (Q)","lineVoltage":"Напруга мережі","lineCurrent":"Лінійний струм","phaseVoltage":"Фазна напруга","phaseCurrent":"Фазний струм","powerFactor":"Коефіцієнт потужності","formula":"Формула","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"Яка формула для збалансованого трифазного живлення?","answer":"Використовуючи напругу між лініями та лінійний струм, повна потужність дорівнює S = √3 × Vline × Iline. \nАктивна потужність P = S × PF. \nЦе передбачає збалансовану синусоїдну систему змінного струму."},{"question":"Яка різниця між зіркою та дельтою?","answer":"Для збалансованого з’єднання зіркою (зіркою) фазна напруга дорівнює лінійній напрузі, поділеній на √3, а фазний струм дорівнює лінійному струму. \nУ дельта фазна напруга дорівнює лінійній напрузі, а фазний струм дорівнює лінійному струму, поділеному на √3. \nЗагальна потужність для однакових значень лінії однакова."},{"question":"Чи впливає коефіцієнт потужності на активну потужність?","answer":"Так. \nАктивна потужність - це уявна потужність, помножена на коефіцієнт потужності. \nНижчий коефіцієнт потужності означає меншу активну потужність за тієї ж напруги та струму в мережі; \nвеличина реактивної потужності оцінюється за S × √(1 − PF²)."},{"question":"Чи можу я використовувати це для незбалансованих навантажень або конструкції електробезпеки?","answer":"Ні. Це ідеалізована оцінка для однофазної або збалансованої трьох фази. \nВін не аналізує незбалансовані фази, гармоніки, електропроводку, номінальні характеристики обладнання, захист, ризик ураження ураженням або пожежею або місцеві електричні норми."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"sw":{"copyLanguage":"sw","name":"Kikokotoo cha Nguvu cha Awamu ya Tatu","title":"Kikokotoo cha Nguvu cha Awamu ya Tatu | UsefulVerse","description":"Kokotoa AC ya awamu moja au tatu inayotumika, inayoonekana na tendaji. \nBure, isiyo na kikomo na kuhesabiwa ndani ya kivinjari chako.","intro":"Kadiria nguvu ya AC kutoka kwa voltage ya mstari, sasa ya mstari na kipengele cha nguvu. \nBadili kati ya mifumo ya awamu moja na iliyosawazishwa ya awamu tatu, na ulinganishe thamani za awamu ya nyota (wye) au delta.","howQuestion":"Je, ninawezaje kukokotoa nguvu za awamu tatu?","howAnswer":"Kwa mfumo wa usawa wa awamu ya tatu, nguvu inayoonekana S = √3 × voltage ya mstari × sasa ya mstari, nguvu inayofanya kazi P = S × kipengele cha nguvu, na ukubwa wa nguvu-tendaji Q = S × √(1 - PF²). \nNguvu inayoonekana ya awamu moja ni V × I. Makadirio haya yanafikiri AC ya sinusoidal na mzigo wa usawa kwa hali ya awamu ya tatu.","privacyQuestion":"Je, thamani zangu za umeme zimepakiwa?","privacyAnswer":"No. Hesabu inaendeshwa katika kivinjari hiki; \nthamani unazoingiza hazijapakiwa au kuhifadhiwa na zana hii.","fields":{"system":"mfumo wa AC","singlePhase":"Awamu moja","threePhase":"Awamu tatu (sawa)","topology":"Uunganisho wa awamu tatu","star":"Nyota / wye","delta":"Delta","lineVoltage":"Voltage ya mstari","voltageUnit":"Kitengo cha voltage\n\nVolti","volts":"Volti (V)","kilovolts":"Kilovolti (kV)","lineCurrent":"Mstari wa sasa","currentUnit":"Kitengo cha sasa","amperes":"Amperes (A)","kiloamperes":"Kiloamperes (kA)","powerFactor":"kipengele cha nguvu (0 hadi 1)","accuracyNote":"Kadirio linalofaa la AC la sinusoidal. \nSababu ya nguvu inachukuliwa kama ukubwa; \nnguvu tendaji inaonyeshwa bila saini. \nMaelewano, usawa wa awamu, kushuka kwa voltage, hali ya muda mfupi, ukubwa wa kondakta, ulinzi, usalama na kufuata kanuni za umeme hazijainishwa. \nTumia data iliyopimwa ya kifaa na ukaguzi wa uhandisi uliohitimu kwa miundo halisi. \nMaadili hubaki kwenye kivinjari hiki."},"actions":{"calculate":"Kokotoa nguvu ya AC","reset":"Weka upya","copy":"Nakili matokeo","example":"Jaribu 400 V, 10 A na PF 0.8","result":"makadirio ya nguvu"},"messages":{"calculated":"makadirio ya nishati ya AC yamekokotolewa.","checkInputs":"Angalia voltage, sasa, kipengele cha nguvu na vitengo vinavyotumika.","activePower":"Nguvu inayotumika (P)","apparentPower":"Nguvu inayoonekana (S)","reactivePower":"Nguvu tendaji ya ukubwa (Q)","lineVoltage":"Voltage ya mstari","lineCurrent":"Line ya sasa","phaseVoltage":"Awamu ya voltage","phaseCurrent":"Awamu ya sasa","powerFactor":"kipengele cha nguvu","formula":"Mfumo","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"Je, ni kanuni gani ya uwiano wa nguvu za awamu tatu?","answer":"Kwa kutumia voltage ya mstari hadi mstari na sasa ya mstari, nguvu inayoonekana ni S = √3 × Vline × Iline. \nNguvu inayotumika ni P = S × PF. \nHii inachukua mfumo wa usawa wa sinusoidal AC."},{"question":"Kuna tofauti gani kati ya nyota na delta?","answer":"Kwa uunganisho wa nyota ya usawa (wye), voltage ya awamu ni voltage ya mstari iliyogawanywa na √3 na sasa ya awamu ni sawa na sasa ya mstari. \nKatika delta, voltage ya awamu inalingana na voltage ya mstari na sasa ya awamu ni ya sasa ya mstari iliyogawanywa na √3. \nNguvu ya jumla ya maadili sawa ya mstari ni sawa."},{"question":"Je, kipengele cha nguvu huathiri nguvu inayotumika?","answer":"Ndiyo. \nNguvu inayotumika ni nguvu inayoonekana inayozidishwa na kipengele cha nguvu. \nSababu ya chini ya nguvu inamaanisha nguvu ndogo ya kazi kwa voltage ya mstari na sasa; \nukubwa wa nguvu-tendaji inakadiriwa kutoka S × √(1 − PF²)."},{"question":"Je, ninaweza kutumia hii kwa mizigo isiyo na usawa au muundo wa usalama wa umeme?","answer":"Hapana. Haya ni makadirio yaliyoboreshwa kwa awamu moja au awamu tatu zilizosawazishwa. \nHaichambui awamu zisizo na usawa, ulinganifu, nyaya, ukadiriaji wa vifaa, ulinzi, mshtuko au hatari ya moto, au misimbo ya umeme ya karibu nawe."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"mr":{"copyLanguage":"mr","name":"थ्री फेज पॉवर कॅल्क्युलेटर","title":"थ्री फेज पॉवर कॅल्क्युलेटर | UsefulVerse","description":"सिंगल- किंवा थ्री-फेज AC सक्रिय, स्पष्ट आणि प्रतिक्रियाशील शक्तीची गणना करा. \nतुमच्या ब्राउझरमध्ये विनामूल्य, अमर्यादित आणि स्थानिक पातळीवर मोजलेले.","intro":"लाइन व्होल्टेज, लाइन करंट आणि पॉवर फॅक्टरवरून AC पॉवरचा अंदाज लावा. \nसिंगल-फेज आणि संतुलित थ्री-फेज सिस्टम दरम्यान स्विच करा आणि स्टार (वाय) किंवा डेल्टा फेज मूल्यांची तुलना करा.","howQuestion":"मी थ्री-फेज पॉवरची गणना कशी करू?","howAnswer":"संतुलित थ्री-फेज सिस्टीमसाठी, स्पष्ट पॉवर S = √3 × रेषा व्होल्टेज × रेषा चालू, सक्रिय पॉवर P = S × पॉवर फॅक्टर आणि रिऍक्टिव्ह-पॉवर परिमाण Q = S × √(1 − PF²). \nसिंगल-फेज उघड पॉवर V × I आहे. हे अंदाज sinusoidal AC आणि तीन-फेज मोडसाठी संतुलित भार गृहीत धरतात.","privacyQuestion":"माझी विद्युत मूल्ये अपलोड केली आहेत का?","privacyAnswer":"क्र. गणना या ब्राउझरमध्ये चालते; \nतुम्ही प्रविष्ट केलेली मूल्ये या साधनाद्वारे अपलोड किंवा जतन केलेली नाहीत.","fields":{"system":"AC प्रणाली","singlePhase":"सिंगल फेज","threePhase":"तीन फेज (संतुलित)","topology":"थ्री-फेज कनेक्शन","star":"तारा / wye","delta":"डेल्टा","lineVoltage":"लाइन व्होल्टेज","voltageUnit":"व्होल्टेज युनिट","volts":"व्होल्ट (V)","kilovolts":"किलोव्होल्ट (kV)","lineCurrent":"लाइन चालू","currentUnit":"वर्तमान युनिट","amperes":"अँपिअर (A)","kiloamperes":"किलोअँपीरेस (kA)","powerFactor":"पॉवर फॅक्टर (0 ते 1)","accuracyNote":"आदर्श संतुलित साइनसॉइडल एसी अंदाज. \nपॉवर फॅक्टरला परिमाण मानले जाते; \nप्रतिक्रियाशील शक्ती स्वाक्षरीशिवाय दर्शविली आहे. \nहार्मोनिक्स, फेज असंतुलन, व्होल्टेज थेंब, क्षणिक परिस्थिती, कंडक्टर आकारमान, संरक्षण, सुरक्षा आणि इलेक्ट्रिकल-कोड अनुपालन मॉडेल केलेले नाहीत. \nवास्तविक डिझाइनसाठी मोजलेले उपकरण डेटा आणि पात्र अभियांत्रिकी पुनरावलोकन वापरा. \nमूल्ये या ब्राउझरमध्ये राहतात."},"actions":{"calculate":"AC पॉवरची गणना करा","reset":"रीसेट करा","copy":"निकाल कॉपी करा","example":"400 V, 10 A आणि PF 0.8 वापरून पहा","result":"पॉवर अंदाज"},"messages":{"calculated":"AC पॉवर अंदाज काढला.","checkInputs":"व्होल्टेज, करंट, पॉवर फॅक्टर आणि सपोर्टेड युनिट तपासा.","activePower":"सक्रिय शक्ती (P)","apparentPower":"स्पष्ट शक्ती (S)","reactivePower":"रिऍक्टिव्ह पॉवर मॅग्निट्यूड (Q)","lineVoltage":"लाइन व्होल्टेज","lineCurrent":"लाइन चालू","phaseVoltage":"फेज व्होल्टेज","phaseCurrent":"टप्पा चालू","powerFactor":"पॉवर फॅक्टर","formula":"सूत्र","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"संतुलित थ्री-फेज पॉवरचे सूत्र काय आहे?","answer":"लाइन-टू-लाइन व्होल्टेज आणि लाइन करंट वापरून, स्पष्ट शक्ती S = √3 × Vline × Iline आहे. \nसक्रिय शक्ती P = S × PF आहे. \nहे एक संतुलित सायनसॉइडल एसी प्रणाली गृहीत धरते."},{"question":"तारा आणि डेल्टामध्ये काय फरक आहे?","answer":"संतुलित तारा (wye) जोडणीसाठी, फेज व्होल्टेज म्हणजे रेषा व्होल्टेज भागिले √3 आणि फेज करंट समान रेषेचा प्रवाह असतो. \nडेल्टामध्ये, फेज व्होल्टेज लाइन व्होल्टेजच्या बरोबरीचे असते आणि फेज करंट √3 ने भागलेला रेषा प्रवाह असतो. \nसमान रेखा मूल्यांसाठी एकूण शक्ती समान आहे."},{"question":"पॉवर फॅक्टर सक्रिय पॉवरवर परिणाम करतो का?","answer":"होय. \nसक्रिय शक्ती म्हणजे पॉवर फॅक्टरने गुणाकार केलेली स्पष्ट शक्ती. \nलोअर पॉवर फॅक्टर म्हणजे समान लाइन व्होल्टेज आणि करंटसाठी कमी सक्रिय शक्ती; \nप्रतिक्रियात्मक-शक्ती परिमाण S × √(1 − PF²) वरून अनुमानित आहे."},{"question":"मी हे असंतुलित भार किंवा विद्युत सुरक्षा डिझाइनसाठी वापरू शकतो का?","answer":"क्र. सिंगल फेज किंवा संतुलित तीन फेजसाठी हा एक आदर्श अंदाज आहे. \nहे असंतुलित टप्पे, हार्मोनिक्स, वायरिंग, उपकरणे रेटिंग, संरक्षण, शॉक किंवा आगीचा धोका किंवा स्थानिक इलेक्ट्रिकल कोडचे विश्लेषण करत नाही."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"te":{"copyLanguage":"te","name":"త్రీ ఫేజ్ పవర్ కాలిక్యులేటర్","title":"త్రీ ఫేజ్ పవర్ కాలిక్యులేటర్ | UsefulVerse","description":"సింగిల్ లేదా త్రీ-ఫేజ్ AC యాక్టివ్, స్పష్టమైన మరియు రియాక్టివ్ పవర్‌ని లెక్కించండి. \nమీ బ్రౌజర్‌లో ఉచిత, అపరిమిత మరియు స్థానికంగా లెక్కించబడుతుంది.","intro":"లైన్ వోల్టేజ్, లైన్ కరెంట్ మరియు పవర్ ఫ్యాక్టర్ నుండి AC పవర్‌ను అంచనా వేయండి. \nసింగిల్-ఫేజ్ మరియు బ్యాలెన్స్‌డ్ త్రీ-ఫేజ్ సిస్టమ్‌ల మధ్య మారండి మరియు స్టార్ (వై) లేదా డెల్టా ఫేజ్ విలువలను సరిపోల్చండి.","howQuestion":"నేను మూడు-దశల శక్తిని ఎలా లెక్కించగలను?","howAnswer":"సమతుల్య మూడు-దశల వ్యవస్థ కోసం, స్పష్టమైన శక్తి S = √3 × లైన్ వోల్టేజ్ × లైన్ కరెంట్, క్రియాశీల శక్తి P = S × పవర్ ఫ్యాక్టర్ మరియు రియాక్టివ్-పవర్ పరిమాణం Q = S × √(1 - PF²). \nసింగిల్-ఫేజ్ స్పష్టమైన శక్తి V × I. ఈ అంచనాలు సైనూసోయిడల్ AC మరియు త్రీ-ఫేజ్ మోడ్‌కు సమతుల్య లోడ్‌ను ఊహిస్తాయి.","privacyQuestion":"నా ఎలక్ట్రికల్ విలువలు అప్‌లోడ్ చేయబడ్డాయా?","privacyAnswer":"నం. ఈ బ్రౌజర్‌లో గణన నడుస్తుంది; \nమీరు నమోదు చేసిన విలువలు ఈ సాధనం ద్వారా అప్‌లోడ్ చేయబడవు లేదా సేవ్ చేయబడవు.","fields":{"system":"AC సిస్టమ్","singlePhase":"సింగిల్ ఫేజ్","threePhase":"మూడు దశలు (సమతుల్యత)","topology":"మూడు-దశల కనెక్షన్","star":"స్టార్ / వై","delta":"డెల్టా","lineVoltage":"లైన్ వోల్టేజ్","voltageUnit":"వోల్టేజ్ యూనిట్","volts":"వోల్ట్‌లు (V)","kilovolts":"కిలోవోల్ట్స్ (కెవి)","lineCurrent":"లైన్ కరెంట్","currentUnit":"ప్రస్తుత యూనిట్","amperes":"ఆంపియర్స్ (A)","kiloamperes":"కిలోఆంపియర్స్ (kA)","powerFactor":"పవర్ ఫ్యాక్టర్ (0 నుండి 1)","accuracyNote":"ఆదర్శ సమతుల్య సైనూసోయిడల్ AC అంచనా. \nపవర్ ఫ్యాక్టర్ పరిమాణంగా పరిగణించబడుతుంది; \nరియాక్టివ్ పవర్ సంతకం చేయనిదిగా చూపబడింది. \nహార్మోనిక్స్, ఫేజ్ అసమతుల్యత, వోల్టేజ్ చుక్కలు, తాత్కాలిక పరిస్థితులు, కండక్టర్ సైజింగ్, రక్షణ, భద్రత మరియు విద్యుత్-కోడ్ సమ్మతి మోడల్ చేయబడలేదు. \nనిజమైన డిజైన్ల కోసం కొలిచిన పరికరాల డేటా మరియు అర్హత కలిగిన ఇంజనీరింగ్ సమీక్షను ఉపయోగించండి. \nవిలువలు ఈ బ్రౌజర్‌లో ఉంటాయి."},"actions":{"calculate":"AC పవర్‌ను లెక్కించండి","reset":"రీసెట్ చేయండి","copy":"ఫలితాలను కాపీ చేయండి","example":"400 V, 10 A మరియు PF 0.8ని ప్రయత్నించండి","result":"పవర్ అంచనా"},"messages":{"calculated":"AC పవర్ అంచనా లెక్కించబడింది.","checkInputs":"వోల్టేజ్, కరెంట్, పవర్ ఫ్యాక్టర్ మరియు సపోర్టెడ్ యూనిట్‌లను తనిఖీ చేయండి.","activePower":"యాక్టివ్ పవర్ (పి)","apparentPower":"స్పష్టమైన శక్తి (S)","reactivePower":"రియాక్టివ్ పవర్ పరిమాణం (Q)","lineVoltage":"లైన్ వోల్టేజ్","lineCurrent":"లైన్ కరెంట్","phaseVoltage":"దశ వోల్టేజ్","phaseCurrent":"ఫేజ్ కరెంట్","powerFactor":"పవర్ ఫ్యాక్టర్","formula":"ఫార్ములా","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"బ్యాలెన్స్డ్ త్రీ-ఫేజ్ పవర్ కోసం ఫార్ములా ఏమిటి?","answer":"లైన్-టు-లైన్ వోల్టేజ్ మరియు లైన్ కరెంట్ ఉపయోగించి, స్పష్టమైన శక్తి S = √3 × Vline × Iline. \nక్రియాశీల శక్తి P = S × PF. \nఇది సమతుల్య సైనూసోయిడల్ AC వ్యవస్థను ఊహిస్తుంది."},{"question":"నక్షత్రం మరియు డెల్టా మధ్య తేడా ఏమిటి?","answer":"సమతుల్య నక్షత్రం (వై) కనెక్షన్ కోసం, ఫేజ్ వోల్టేజ్ అనేది లైన్ వోల్టేజ్ √3తో విభజించబడింది మరియు ఫేజ్ కరెంట్ లైన్ కరెంట్‌కు సమానం. \nడెల్టాలో, ఫేజ్ వోల్టేజ్ లైన్ వోల్టేజీకి సమానం మరియు ఫేజ్ కరెంట్ అనేది లైన్ కరెంట్ √3తో భాగించబడుతుంది. \nఅదే పంక్తి విలువలకు మొత్తం శక్తి ఒకే విధంగా ఉంటుంది."},{"question":"పవర్ ఫ్యాక్టర్ క్రియాశీల శక్తిని ప్రభావితం చేస్తుందా?","answer":"అవును. \nక్రియాశీల శక్తి అనేది పవర్ ఫ్యాక్టర్ ద్వారా గుణించబడిన స్పష్టమైన శక్తి. \nతక్కువ పవర్ ఫ్యాక్టర్ అంటే అదే లైన్ వోల్టేజ్ మరియు కరెంట్ కోసం తక్కువ యాక్టివ్ పవర్; \nరియాక్టివ్-పవర్ పరిమాణం S × √(1 − PF²) నుండి అంచనా వేయబడింది."},{"question":"నేను అసమతుల్య లోడ్లు లేదా విద్యుత్ భద్రత రూపకల్పన కోసం దీనిని ఉపయోగించవచ్చా?","answer":"నం. ఇది సింగిల్ ఫేజ్ లేదా బ్యాలెన్స్‌డ్ త్రీ ఫేజ్‌కి ఆదర్శప్రాయమైన అంచనా. \nఇది అసమతుల్య దశలు, హార్మోనిక్స్, వైరింగ్, పరికరాల రేటింగ్‌లు, రక్షణ, షాక్ లేదా అగ్ని ప్రమాదం లేదా స్థానిక విద్యుత్ కోడ్‌లను విశ్లేషించదు."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"ha":{"copyLanguage":"ha","name":"Kalkuletattar Wuta ta Mataki Uku","title":"Kalkuletattar Wuta ta Mataki Uku | UsefulVerse","description":"Ƙididdigar AC mai aiki ɗaya- ko uku-uku, bayyane da ƙarfin amsawa. \nKyauta, mara iyaka da ƙididdige su a cikin mazuruftan ku.","intro":"Ƙididdiga ƙarfin AC daga ƙarfin layi, halin yanzu da ƙarfin wuta. \nCanja tsakanin tsarin lokaci-ɗaya da madaidaitan tsarin matakai uku, kuma kwatanta darajar tauraro (wye) ko darajar lokaci na delta.","howQuestion":"Ta yaya zan lissafta iko uku?","howAnswer":"Don daidaitaccen tsarin matakai uku, bayyananniyar wutar lantarki S = √3 × layin ƙarfin lantarki × layin yanzu, ƙarfin aiki P = S × factor factor, da girman amsa-ikon Q = S × √ (1 - PF²). \nƘarfin bayyane ɗaya-lokaci shine V × I. Waɗannan ƙididdiga sun ɗauka sinusoidal AC da ma'auni mai daidaitacce don yanayin mataki uku.","privacyQuestion":"Ana loda ma'aunin lantarki na?","privacyAnswer":"A'a. Lissafin yana gudana a cikin wannan browser; \nBa a loda kimar da kuka shigar ta wannan kayan aikin ba.","fields":{"system":"AC tsarin","singlePhase":"Single lokaci","threePhase":"Mataki na uku (daidaitacce)","topology":"Haɗin mataki uku","star":"Tauraro / wye","delta":"Delta","lineVoltage":"Wutar lantarki","voltageUnit":"Naúrar wutar lantarki","volts":"V (V)","kilovolts":"kilovolts (kV)","lineCurrent":"Layi na yanzu","currentUnit":"Naúrar yanzu","amperes":"Amperes (A)","kiloamperes":"Kiloamperes (kA)","powerFactor":"Factor Power (0 zuwa 1)","accuracyNote":"Madaidaicin ma'auni na sinusoidal AC kimanta. \nAna kula da factor factor a matsayin girma; \nAna nuna ikon amsawa ba a sanya hannu ba. \nMasu jituwa, rashin daidaiton lokaci, faɗuwar wutar lantarki, yanayi na wucin gadi, girman madugu, kariya, aminci da ƙa'idodin lambar lantarki ba a tsara su ba. \nYi amfani da bayanan kayan aiki da aka auna da ƙwararrun injiniyan bita don ƙira na gaske. \nƘimar ta tsaya a cikin wannan mai binciken."},"actions":{"calculate":"Yi lissafin ikon AC","reset":"Sake saiti","copy":"Kwafi sakamakon","example":"Gwada 400 V, 10 A da PF 0.8","result":"Ƙimar wutar lantarki"},"messages":{"calculated":"AC ƙididdiga ƙarfin lantarki.","checkInputs":"Duba ƙarfin lantarki, halin yanzu, ƙarfin wuta da raka'a masu goyan baya.","activePower":"Ikon aiki (P)","apparentPower":"Ƙarfin Ƙarfi (S)","reactivePower":"Girman ƙarfin amsawa (Q)","lineVoltage":"Layin wutar lantarki","lineCurrent":"Layi na yanzu","phaseVoltage":"Matsayin ƙarfin lantarki","phaseCurrent":"Matsayi na yanzu","powerFactor":"Factor","formula":"Formula","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"Menene ma'auni na daidaitattun iko na matakai uku?","answer":"Yin amfani da wutar lantarki na layi-zuwa-layi da layin yanzu, ƙarfin da yake gani shine S = √3 × Vline × Iline. \nIkon aiki shine P = S × PF. \nWannan yana ɗaukar daidaitaccen tsarin sinusoidal AC."},{"question":"Menene bambanci tsakanin tauraro da delta?","answer":"Domin madaidaicin haɗin tauraro (wye), ƙarfin ƙarfin lokaci shine layin wutan lantarki da aka raba da √3 kuma lokaci na yanzu yana daidai da halin yanzu. \nA cikin delta, ƙarfin lantarki na zamani yana daidai da ƙarfin lantarki kuma lokaci na yanzu shine layin yanzu wanda aka raba da √3. \nJimillar ƙarfi don ƙimar layi ɗaya ɗaya ce."},{"question":"Shin tasirin wutar lantarki yana shafar ikon aiki?","answer":"iya. \nƘarfin aiki yana bayyana ikon da aka ninka ta hanyar ƙarfin wuta. \nƘananan ƙarfin wutar lantarki yana nufin ƙarancin ƙarfin aiki don irin ƙarfin lantarki iri ɗaya da na yanzu; \nAn kiyasta girman ƙarfin amsawa daga S × √(1 - PF²)."},{"question":"Zan iya amfani da wannan don kaya marasa daidaituwa ko ƙirar amincin lantarki?","answer":"A'a. Wannan ƙididdigewa ce mai ƙayyadaddun ƙididdiga don lokaci ɗaya ko daidaita kashi uku. \nBa ya nazarin matakan da ba su daidaita ba, masu jituwa, wayoyi, ƙimar kayan aiki, kariya, girgiza ko haɗarin wuta, ko lambobin lantarki na gida."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"tl":{"copyLanguage":"tl","name":"Kalkulador ng Three-Phase Power","title":"Three-Phase Power Calculator Libre | UsefulVerse","description":"Kalkulahin ang single- o three-phase AC na aktibo, maliwanag at reaktibo na kapangyarihan. \nLibre, walang limitasyon at lokal na kinakalkula sa iyong browser.","intro":"Tantyahin ang AC power mula sa line voltage, line current at power factor. \nLumipat sa pagitan ng single-phase at balanseng three-phase system, at ihambing ang star (wye) o delta phase value.","howQuestion":"Paano ko kalkulahin ang three-phase power?","howAnswer":"Para sa isang balanseng three-phase system, maliwanag na power S = √3 × line voltage × line current, active power P = S × power factor, at reactive-power magnitude Q = S × √(1 − PF²). \nAng single-phase na maliwanag na kapangyarihan ay V × I. Ipinapalagay ng mga pagtatantyang ito ang sinusoidal AC at isang balanseng pagkarga para sa three-phase mode.","privacyQuestion":"Na-upload ba ang aking mga electrical value?","privacyAnswer":"Hindi. Ang pagkalkula ay tumatakbo sa browser na ito; \nang mga halagang ipinasok mo ay hindi ina-upload o nai-save ng tool na ito.","fields":{"system":"AC system","singlePhase":"Isang yugto","threePhase":"Tatlong yugto (balanseng)","topology":"Three-phase na koneksyon","star":"Bituin / wye","delta":"Delta","lineVoltage":"Linya na boltahe","voltageUnit":"Yunit ng boltahe","volts":"Volts (V)","kilovolts":"Kilovolts (kV)","lineCurrent":"Kasalukuyang linya","currentUnit":"Kasalukuyang unit","amperes":"Amperes (A)","kiloamperes":"Kiloamperes (kA)","powerFactor":"Power factor (0 hanggang 1)","accuracyNote":"Mainam na balanseng sinusoidal AC na pagtatantya. \nAng power factor ay itinuturing bilang isang magnitude; \nang reaktibong kapangyarihan ay ipinapakita na hindi nakapirma. \nAng mga harmonika, phase imbalance, pagbaba ng boltahe, lumilipas na kundisyon, sukat ng conductor, proteksyon, kaligtasan at pagsunod sa electrical-code ay hindi modelo. \nGumamit ng data ng nasusukat na kagamitan at kwalipikadong pagsusuri sa engineering para sa mga tunay na disenyo. \nAng mga halaga ay nananatili sa browser na ito."},"actions":{"calculate":"Kalkulahin ang AC power","reset":"I-reset","copy":"Kopyahin ang mga resulta","example":"Subukan ang 400 V, 10 A at PF 0.8","result":"Power estimate"},"messages":{"calculated":"AC power estimate ang kinakalkula.","checkInputs":"Suriin ang boltahe, kasalukuyang, power factor at mga sinusuportahang unit.","activePower":"Aktibong kapangyarihan (P)","apparentPower":"Mistulang kapangyarihan (S)","reactivePower":"Reactive power magnitude (Q)","lineVoltage":"Linya na boltahe","lineCurrent":"Kasalukuyang linya","phaseVoltage":"Phase boltahe","phaseCurrent":"Phase kasalukuyang","powerFactor":"Power factor","formula":"Formula","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"Ano ang formula para sa balanseng three-phase power?","answer":"Gamit ang line-to-line na boltahe at line current, ang maliwanag na kapangyarihan ay S = √3 × Vline × Iline. \nAng aktibong kapangyarihan ay P = S × PF. \nIpinapalagay nito ang isang balanseng sinusoidal AC system."},{"question":"Ano ang pagkakaiba ng star at delta?","answer":"Para sa balanseng star (wye) na koneksyon, ang boltahe ng phase ay boltahe ng linya na hinati ng √3 at ang kasalukuyang phase ay katumbas ng kasalukuyang linya. \nSa delta, ang boltahe ng phase ay katumbas ng boltahe ng linya at ang kasalukuyang bahagi ay ang kasalukuyang linya na hinati ng √3. \nAng kabuuang kapangyarihan para sa parehong mga halaga ng linya ay pareho."},{"question":"Nakakaapekto ba ang power factor sa aktibong power?","answer":"Oo. \nAng aktibong kapangyarihan ay maliwanag na kapangyarihan na pinarami ng power factor. \nAng mas mababang power factor ay nangangahulugang hindi gaanong aktibong kapangyarihan para sa parehong boltahe at kasalukuyang linya; \nang reactive-power magnitude ay tinatantya mula sa S × √(1 − PF²)."},{"question":"Maaari ko bang gamitin ito para sa hindi balanseng pagkarga o disenyo ng kaligtasan sa kuryente?","answer":"Hindi. Ito ay isang ideyal na pagtatantya para sa isang yugto o balanseng tatlong yugto. \nHindi nito sinusuri ang mga hindi balanseng yugto, harmonika, mga kable, mga rating ng kagamitan, proteksyon, panganib sa pagkabigla o sunog, o mga lokal na electrical code."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"ta":{"copyLanguage":"ta","name":"மூன்று கட்ட பவர் கால்குலேட்டர்","title":"மூன்று கட்ட பவர் கால்குலேட்டர் | UsefulVerse","description":"ஒற்றை அல்லது மூன்று-கட்ட ஏசி செயலில், வெளிப்படையான மற்றும் எதிர்வினை சக்தியைக் கணக்கிடுங்கள். \nஇலவசம், வரம்பற்றது மற்றும் உங்கள் உலாவியில் உள்ளூரில்...","intro":"லைன் வோல்டேஜ், லைன் கரண்ட் மற்றும் பவர் ஃபேக்டர் ஆகியவற்றிலிருந்து ஏசி பவரை மதிப்பிடவும். \nஒற்றை-கட்ட மற்றும் சமநிலையான மூன்று-கட்ட அமைப்புகளுக்கு இடையில் மாறவும், மேலும் நட்சத்திரம் (வை) அல்லது டெல்டா கட்ட மதிப்புகளை ஒப்பிடவும்.","howQuestion":"நான் எப்படி மூன்று கட்ட சக்தியைக் கணக்கிடுவது?","howAnswer":"ஒரு சமநிலையான மூன்று-கட்ட அமைப்புக்கு, வெளிப்படையான சக்தி S = √3 × வரி மின்னழுத்தம் × வரி மின்னோட்டம், செயலில் ஆற்றல் P = S × சக்தி காரணி, மற்றும் எதிர்வினை-சக்தி அளவு Q = S × √(1 − PF²). \nஒற்றை-கட்ட வெளிப்படையான சக்தி V × I. இந்த மதிப்பீடுகள் சைனூசாய்டல் ஏசி மற்றும் மூன்று-கட்ட பயன்முறையில் ஒரு சமநிலையான சுமை ஆகியவற்றைக் கருதுகின்றன.","privacyQuestion":"எனது மின் மதிப்புகள் பதிவேற்றப்பட்டதா?","privacyAnswer":"எண். கணக்கீடு இந்த உலாவியில் இயங்குகிறது; \nநீங்கள் உள்ளிடும் மதிப்புகள் இந்தக் கருவியால் பதிவேற்றப்படவில்லை அல்லது சேமிக்கப்படவில்லை.","fields":{"system":"ஏசி சிஸ்டம்","singlePhase":"ஒற்றை கட்டம்","threePhase":"மூன்று கட்டம் (சமநிலை)","topology":"மூன்று கட்ட இணைப்பு","star":"நட்சத்திரம் / வை","delta":"டெல்டா","lineVoltage":"வரி மின்னழுத்தம்","voltageUnit":"மின்னழுத்த அலகு","volts":"வோல்ட்ஸ் (V)","kilovolts":"கிலோவோல்ட்ஸ் (kV)","lineCurrent":"வரி மின்னோட்டம்","currentUnit":"தற்போதைய அலகு","amperes":"ஆம்பியர்ஸ் (A)","kiloamperes":"கிலோஆம்பியர்ஸ் (kA)","powerFactor":"ஆற்றல் காரணி (0 முதல் 1 வரை)","accuracyNote":"ஐடியல் பேலன்ஸ்டு சைனூசாய்டல் ஏசி மதிப்பீடு. \nசக்தி காரணி ஒரு அளவு கருதப்படுகிறது; \nஎதிர்வினை சக்தி கையொப்பமிடப்படாமல் காட்டப்பட்டுள்ளது. \nஹார்மோனிக்ஸ், கட்ட ஏற்றத்தாழ்வு, மின்னழுத்த வீழ்ச்சிகள், நிலையற்ற நிலைகள், கடத்தி அளவு, பாதுகாப்பு, பாதுகாப்பு மற்றும் மின்-குறியீடு இணக்கம் மாதிரியாக இல்லை. \nஉண்மையான வடிவமைப்புகளுக்கு அளவிடப்பட்ட உபகரணத் தரவு மற்றும் தகுதியான பொறியியல் மதிப்பாய்வைப் பயன்படுத்தவும். \nஇந்த உலாவியில் மதிப்புகள் இருக்கும்."},"actions":{"calculate":"ஏசி பவரைக் கணக்கிடவும்","reset":"மீட்டமை","copy":"முடிவுகளை நகலெடுக்கவும்","example":"400 V, 10 A மற்றும் PF 0.8 ஐ முயற்சிக்கவும்","result":"பவர் மதிப்பீடு"},"messages":{"calculated":"ஏசி பவர் மதிப்பீடு கணக்கிடப்பட்டது.","checkInputs":"மின்னழுத்தம், மின்னோட்டம், சக்தி காரணி மற்றும் ஆதரிக்கப்படும் அலகுகளைச் சரிபார்க்கவும்.","activePower":"ஆக்டிவ் பவர் (பி)","apparentPower":"வெளிப்படையான சக்தி (எஸ்)","reactivePower":"எதிர்வினை சக்தி அளவு (Q)","lineVoltage":"வரி மின்னழுத்தம்","lineCurrent":"வரி மின்னோட்டம்","phaseVoltage":"கட்ட மின்னழுத்தம்","phaseCurrent":"கட்ட மின்னோட்டம்","powerFactor":"சக்தி காரணி","formula":"சூத்திரம்","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"சமச்சீர் மூன்று-கட்ட சக்திக்கான சூத்திரம் என்ன?","answer":"வரி-க்கு-வரி மின்னழுத்தம் மற்றும் வரி மின்னோட்டத்தைப் பயன்படுத்தி, வெளிப்படையான சக்தி S = √3 × Vline × Iline ஆகும். \nசெயலில் உள்ள சக்தி P = S × PF ஆகும். \nஇது ஒரு சீரான சைனூசாய்டல் ஏசி அமைப்பைக் கருதுகிறது."},{"question":"நட்சத்திரத்திற்கும் டெல்டாவிற்கும் என்ன வித்தியாசம்?","answer":"ஒரு சமநிலை நட்சத்திர (வை) இணைப்புக்கு, கட்ட மின்னழுத்தம் என்பது வரி மின்னழுத்தம் √3 ஆல் வகுக்கப்படுகிறது மற்றும் கட்ட மின்னோட்டம் வரி மின்னோட்டத்திற்கு சமம். \nடெல்டாவில், கட்ட மின்னழுத்தம் வரி மின்னழுத்தத்திற்கு சமம் மற்றும் கட்ட மின்னோட்டம் என்பது வரி மின்னோட்டத்தை √3 ஆல் வகுக்கப்படுகிறது. \nஒரே வரி மதிப்புகளுக்கான மொத்த சக்தி ஒன்றுதான்."},{"question":"ஆற்றல் காரணி செயலில் உள்ள ஆற்றலைப் பாதிக்குமா?","answer":"ஆம். \nசெயலில் உள்ள ஆற்றல் என்பது ஆற்றல் காரணியால் பெருக்கப்படும் வெளிப்படையான சக்தியாகும். \nகுறைந்த சக்தி காரணி என்பது அதே வரி மின்னழுத்தம் மற்றும் மின்னோட்டத்திற்கான குறைவான செயலில் உள்ள சக்தியைக் குறிக்கிறது; \nஎதிர்வினை-சக்தி அளவு S × √(1 - PF²) இலிருந்து மதிப்பிடப்படுகிறது."},{"question":"சமநிலையற்ற சுமைகளுக்கு அல்லது மின் பாதுகாப்பு வடிவமைப்பிற்கு இதைப் பயன்படுத்தலாமா?","answer":"எண். இது ஒற்றை கட்டம் அல்லது சமச்சீர் மூன்று கட்டத்திற்கான சிறந்த மதிப்பீடாகும். \nஇது சமநிலையற்ற கட்டங்கள், ஹார்மோனிக்ஸ், வயரிங், உபகரணங்கள் மதிப்பீடுகள், பாதுகாப்பு, அதிர்ச்சி அல்லது தீ ஆபத்து அல்லது உள்ளூர் மின் குறியீடுகளை பகுப்பாய்வு செய்யாது."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"fa":{"copyLanguage":"fa","name":"ماشین حساب برق سه فاز","title":"ماشین حساب برق سه فاز | UsefulVerse","description":"برق AC تک یا سه فاز اکتیو، ظاهری و راکتیو را محاسبه کنید. \nرایگان، نامحدود و به صورت محلی در مرورگر شما محاسبه می شود.","intro":"توان AC را از ولتاژ خط، جریان خط و ضریب توان تخمین بزنید. \nبین سیستم های سه فاز تک فاز و متعادل جابجا شوید و مقادیر فاز ستاره (wye) یا مثلث را مقایسه کنید.","howQuestion":"چگونه برق سه فاز را محاسبه کنم؟","howAnswer":"برای یک سیستم سه فاز متعادل، توان ظاهری S = √3 × ولتاژ خط × جریان خط، توان فعال P = S × ضریب توان، و قدر توان راکتیو Q = S × √ (1 - PF²). \nتوان ظاهری تک فاز V × I است. این برآوردها AC سینوسی و یک بار متعادل را برای حالت سه فاز فرض می‌کنند.","privacyQuestion":"آیا مقادیر الکتریکی من آپلود شده است؟","privacyAnswer":"شماره محاسبه در این مرورگر انجام می شود. \nمقادیری که وارد می کنید توسط این ابزار آپلود یا ذخیره نمی شوند.","fields":{"system":"سیستم AC","singlePhase":"تکفاز","threePhase":"سه فاز (متعادل)","topology":"اتصال سه فاز","star":"ستاره / وای","delta":"دلتا","lineVoltage":"ولتاژ خط","voltageUnit":"واحد ولتاژ","volts":"ولت (V)","kilovolts":"کیلوولت (کیلوولت)","lineCurrent":"جریان خط","currentUnit":"واحد فعلی","amperes":"آمپر (A)","kiloamperes":"کیلو آمپر (کیلو آمپر)","powerFactor":"ضریب توان (0 تا 1)","accuracyNote":"برآورد AC سینوسی متعادل. \nضریب توان به عنوان یک بزرگی در نظر گرفته می شود. \nتوان راکتیو بدون علامت نشان داده می شود. \nهارمونیک ها، عدم تعادل فاز، افت ولتاژ، شرایط گذرا، اندازه هادی، حفاظت، ایمنی و انطباق با کد الکتریکی مدل سازی نشده اند. \nاز داده های تجهیزات اندازه گیری شده و بررسی مهندسی واجد شرایط برای طرح های واقعی استفاده کنید. \nارزش ها در این مرورگر باقی می مانند."},"actions":{"calculate":"برق متناوب را محاسبه کنید","reset":"ریست","copy":"کپی نتایج","example":"400 V، 10 A و PF 0.8 را امتحان کنید","result":"برآورد توان"},"messages":{"calculated":"برآورد برق AC محاسبه شده است.","checkInputs":"ولتاژ، جریان، ضریب توان و واحدهای پشتیبانی شده را بررسی کنید.","activePower":"توان فعال (P)","apparentPower":"قدرت ظاهری (S)","reactivePower":"قدر توان راکتیو (Q)","lineVoltage":"ولتاژ خط","lineCurrent":"جریان خط","phaseVoltage":"ولتاژ فاز","phaseCurrent":"جریان فاز","powerFactor":"ضریب توان","formula":"فرمول","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"فرمول برق سه فاز متعادل چیست؟","answer":"با استفاده از ولتاژ خط به خط و جریان خط، توان ظاهری S = √3 × Vline × Iline است. \nتوان فعال P = S × PF است. \nاین یک سیستم AC سینوسی متعادل را فرض می کند."},{"question":"تفاوت ستاره و دلتا چیست؟","answer":"برای اتصال ستاره متعادل (wye)، ولتاژ فاز ولتاژ خط تقسیم بر √3 و جریان فاز برابر با جریان خط است. \nدر دلتا، ولتاژ فاز برابر با ولتاژ خط است و جریان فاز، جریان خط تقسیم بر √3 است. \nتوان کل برای مقادیر یکسان خط یکسان است."},{"question":"آیا ضریب توان بر توان اکتیو تأثیر می گذارد؟","answer":"بله. \nتوان اکتیو توان ظاهری ضربدر ضریب توان است. \nضریب توان کمتر به معنای توان فعال کمتر برای ولتاژ و جریان یکسان خط است. \nقدر توان راکتیو از S × √ (1 - PF2) تخمین زده می شود."},{"question":"آیا می توانم از این برای بارهای نامتعادل یا طراحی ایمنی الکتریکی استفاده کنم؟","answer":"شماره. این یک برآورد ایده آل برای تک فاز یا سه فاز متعادل است. \nفازهای نامتعادل، هارمونیک ها، سیم کشی ها، درجه بندی تجهیزات، حفاظت، خطر شوک یا آتش سوزی، یا کدهای الکتریکی محلی را تجزیه و تحلیل نمی کند."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"am":{"copyLanguage":"am","name":"የሶስት ደረጃ የኃይል ማስያ","title":"የሶስት ደረጃ የኃይል ማስያ | UsefulVerse","description":"ነጠላ ወይም ሶስት-ደረጃ AC ገባሪ፣ ግልጽ እና ምላሽ ሰጪ ሃይልን አስላ። \nነፃ፣ ያልተገደበ እና በአሳሽዎ ውስጥ በአካባቢው የሚሰላ።","intro":"የኤሲ ሃይልን ከመስመር ቮልቴጅ፣የመስመር ጅረት እና የሃይል ፋክተር ይገምቱ። \nበነጠላ-ደረጃ እና በተመጣጣኝ የሶስት-ደረጃ ስርዓቶች መካከል ይቀያይሩ፣ እና የኮከብ (wye) ወይም የዴልታ ምዕራፍ እሴቶችን ያወዳድሩ።","howQuestion":"የሶስት-ደረጃ ኃይልን እንዴት ማስላት እችላለሁ?","howAnswer":"ለተመጣጣኝ የሶስት-ደረጃ ስርዓት ግልጽ ሃይል S = √3 × መስመር የቮልቴጅ × መስመር ጅረት፣ ገባሪ ሃይል P = S × ሃይል ፋክተር እና ምላሽ-የኃይል መጠን Q = S × √(1 - PF²)። \nነጠላ-ደረጃ ግልጽ ኃይል V × I ነው. እነዚህ ግምቶች የ sinusoidal AC እና ለሶስት-ደረጃ ሁነታ የተመጣጠነ ሸክም ይወስዳሉ.","privacyQuestion":"የኤሌክትሪክ እሴቶቼ ተሰቅለዋል?","privacyAnswer":"አይ ስሌቱ በዚህ አሳሽ ውስጥ ይሰራል; \nየሚያስገቧቸው እሴቶች በዚህ መሣሪያ አልተሰቀሉም ወይም አልተቀመጡም።","fields":{"system":"AC ስርዓት","singlePhase":"ነጠላ ደረጃ","threePhase":"ሶስት ደረጃ (ሚዛናዊ)","topology":"የሶስት-ደረጃ ግንኙነት","star":"ኮከብ / ዋይ","delta":"ዴልታ","lineVoltage":"የመስመር ቮልቴጅ","voltageUnit":"የቮልቴጅ አሃድ","volts":"ቮልት (ቪ)","kilovolts":"ኪሎ ቮልት (ኪ.ወ)","lineCurrent":"የአሁኑ መስመር","currentUnit":"የአሁኑ ክፍል","amperes":"Amperes (ኤ)","kiloamperes":"ኪሎአምፐርስ (ኬኤ)","powerFactor":"የኃይል መጠን (0 ለ 1)","accuracyNote":"ተስማሚ ሚዛናዊ የ sinusoidal AC ግምት። \nየኃይል ሁኔታ እንደ መጠን ይቆጠራል; \nምላሽ ሰጪ ሃይል ሳይፈረም ይታያል። \nሃርሞኒክስ፣ የደረጃ አለመመጣጠን፣ የቮልቴጅ ጠብታዎች፣ ጊዜያዊ ሁኔታዎች፣ የመቆጣጠሪያ መጠን፣ ጥበቃ፣ ደህንነት እና ኤሌክትሪክ-ኮድ ተገዢነት አልተቀረጹም። \nለትክክለኛ ዲዛይኖች የሚለካ መሳሪያ መረጃ እና ብቁ የሆነ የምህንድስና ግምገማ ተጠቀም። \nእሴቶች በዚህ አሳሽ ውስጥ ይቀራሉ።"},"actions":{"calculate":"የ AC ሃይል አስላ","reset":"ዳግም አስጀምር","copy":"ውጤቶች ቅዳ","example":"ይሞክሩ 400 V፣ 10 A እና PF 0.8","result":"የኃይል ግምት"},"messages":{"calculated":"AC ሃይል ግምት ይሰላል።","checkInputs":"የቮልቴጅ, የአሁን, የኃይል መጠን እና የሚደገፉ ክፍሎችን ይፈትሹ.","activePower":"ንቁ ኃይል (ፒ)","apparentPower":"ግልጽ ኃይል (ኤስ)","reactivePower":"ምላሽ ሰጪ የኃይል መጠን (Q)","lineVoltage":"የመስመር ቮልቴጅ","lineCurrent":"የአሁኑ መስመር","phaseVoltage":"ደረጃ ቮልቴጅ","phaseCurrent":"ደረጃ ወቅታዊ","powerFactor":"የኃይል ምክንያት","formula":"ቀመር","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"ሚዛናዊ የሶስት-ደረጃ ሃይል ቀመር ምንድ ነው?","answer":"ከመስመር ወደ መስመር የቮልቴጅ እና የመስመር ጅረት በመጠቀም የሚታየው ሃይል S = √3 × Vline × Iline ነው። \nንቁ ኃይል P = S × PF ነው. \nይህ የተመጣጠነ የ sinusoidal AC ስርዓት ነው."},{"question":"በኮከብ እና በዴልታ መካከል ያለው ልዩነት ምንድን ነው?","answer":"ለተመጣጣኝ ኮከብ (wye) ግንኙነት የፍዝ ቮልቴጅ የመስመር ቮልቴጅ በ√3 የተከፋፈለ ሲሆን የፋዝ አሁኑን ደግሞ የመስመር አሁኑን እኩል ነው። \nበዴልታ ውስጥ የፔዝ ቮልቴጅ ከመስመር ቮልቴጅ ጋር እኩል ሲሆን የፋዝ አሁኑ ደግሞ የመስመር አሁኑ በ√3 ይከፈላል። \nለተመሳሳይ መስመር ዋጋዎች አጠቃላይ ኃይል ተመሳሳይ ነው."},{"question":"የሃይል ፋክተር ንቁ ሃይልን ይነካል?","answer":"አዎ። \nገባሪ ሃይል በኃይል ተባዝቶ ይታያል። \nዝቅተኛ ኃይል ምክንያት ለተመሳሳይ መስመር ቮልቴጅ እና የአሁኑ ያነሰ ንቁ ኃይል; \nአጸፋዊ-ኃይል መጠን ከ S × √(1 - PF²) ይገመታል።"},{"question":"ይህንን ያልተመጣጠነ ጭነት ወይም የኤሌክትሪክ ደህንነት ዲዛይን መጠቀም እችላለሁ?","answer":"ቁጥር ይህ ለነጠላ ደረጃ ወይም ለተመጣጣኝ የሶስት ምእራፍ ሃሳባዊ ግምት ነው። \nያልተመጣጠነ ደረጃዎችን፣ ሃርሞኒኮችን፣ ሽቦዎችን፣ የመሳሪያ ደረጃዎችን፣ ጥበቃን፣ ድንጋጤን ወይም የእሳት አደጋን ወይም የአካባቢ ኤሌክትሪክ ኮዶችን አይተነተንም።"}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"},"gu":{"copyLanguage":"gu","name":"થ્રી ફેઝ પાવર કેલ્ક્યુલેટર","title":"થ્રી ફેઝ પાવર કેલ્ક્યુલેટર | UsefulVerse","description":"સિંગલ- અથવા થ્રી-ફેઝ AC સક્રિય, દેખીતી અને પ્રતિક્રિયાશીલ શક્તિની ગણતરી કરો. \nતમારા બ્રાઉઝરમાં મફત, અમર્યાદિત અને સ્થાનિક રીતે ગણતરી કરેલ.","intro":"લાઇન વોલ્ટેજ, લાઇન કરંટ અને પાવર ફેક્ટર પરથી AC પાવરનો અંદાજ કાઢો. \nસિંગલ-ફેઝ અને બેલેન્સ્ડ થ્રી-ફેઝ સિસ્ટમ્સ વચ્ચે સ્વિચ કરો અને સ્ટાર (wye) અથવા ડેલ્ટા ફેઝ વેલ્યુની તુલના કરો.","howQuestion":"હું થ્રી-ફેઝ પાવરની ગણતરી કેવી રીતે કરી શકું?","howAnswer":"સંતુલિત થ્રી-ફેઝ સિસ્ટમ માટે, દેખીતી શક્તિ S = √3 × લાઇન વોલ્ટેજ × રેખા વર્તમાન, સક્રિય શક્તિ P = S × પાવર પરિબળ અને પ્રતિક્રિયાશીલ-પાવર મેગ્નિટ્યુડ Q = S × √(1 − PF²). \nએકલ-તબક્કાની દેખીતી શક્તિ V × I છે. આ અંદાજો ત્રણ-તબક્કાના મોડ માટે sinusoidal AC અને સંતુલિત લોડ ધારે છે.","privacyQuestion":"શું મારા વિદ્યુત મૂલ્યો અપલોડ કરવામાં આવ્યા છે?","privacyAnswer":"નંબર. આ બ્રાઉઝરમાં ગણતરી ચાલે છે; \nતમે દાખલ કરેલ મૂલ્યો આ સાધન દ્વારા અપલોડ અથવા સાચવવામાં આવતા નથી.","fields":{"system":"એસી સિસ્ટમ","singlePhase":"સિંગલ ફેઝ","threePhase":"ત્રણ તબક્કા (સંતુલિત)","topology":"થ્રી-ફેઝ કનેક્શન","star":"સ્ટાર/વાય","delta":"ડેલ્ટા","lineVoltage":"લાઇન વોલ્ટેજ","voltageUnit":"વોલ્ટેજ યુનિટ","volts":"વોલ્ટ (V)","kilovolts":"કિલોવોલ્ટ (kV)","lineCurrent":"રેખા વર્તમાન","currentUnit":"વર્તમાન એકમ","amperes":"એમ્પીયર (A)","kiloamperes":"કિલોએમ્પીરેસ (kA)","powerFactor":"પાવર ફેક્ટર (0 થી 1)","accuracyNote":"આદર્શ સંતુલિત sinusoidal AC અંદાજ. \nપાવર ફેક્ટરને તીવ્રતા તરીકે ગણવામાં આવે છે; \nપ્રતિક્રિયાશીલ શક્તિ સહી વગર બતાવવામાં આવે છે. \nહાર્મોનિક્સ, તબક્કાનું અસંતુલન, વોલ્ટેજ ડ્રોપ્સ, ક્ષણિક પરિસ્થિતિઓ, વાહક કદ બદલવાનું, રક્ષણ, સલામતી અને વિદ્યુત-કોડ અનુપાલનનું મોડેલિંગ નથી. \nવાસ્તવિક ડિઝાઇન માટે માપેલા સાધનોના ડેટા અને લાયક એન્જિનિયરિંગ સમીક્ષાનો ઉપયોગ કરો. \nમૂલ્યો આ બ્રાઉઝરમાં રહે છે."},"actions":{"calculate":"AC પાવરની ગણતરી કરો","reset":"રીસેટ કરો","copy":"પરિણામોની નકલ કરો","example":"400 V, 10 A અને PF 0.8 અજમાવી જુઓ","result":"પાવર અંદાજ"},"messages":{"calculated":"AC પાવર અંદાજની ગણતરી.","checkInputs":"વોલ્ટેજ, કરંટ, પાવર ફેક્ટર અને સપોર્ટેડ યુનિટ તપાસો.","activePower":"સક્રિય શક્તિ (P)","apparentPower":"દેખીતી શક્તિ (S)","reactivePower":"રિએક્ટિવ પાવર મેગ્નિટ્યુડ (Q)","lineVoltage":"લાઇન વોલ્ટેજ","lineCurrent":"રેખા વર્તમાન","phaseVoltage":"તબક્કો વોલ્ટેજ","phaseCurrent":"તબક્કો વર્તમાન","powerFactor":"પાવર ફેક્ટર","formula":"ફોર્મ્યુલા","singlePhaseFormula":"S = V × I; P = S × PF; Q = S × √(1 − PF²)","threePhaseFormula":"S = √3 × Vline × Iline; P = S × PF; Q = S × √(1 − PF²)"},"additionalFaqs":[{"question":"સંતુલિત થ્રી-ફેઝ પાવર માટેનું સૂત્ર શું છે?","answer":"લાઇન-ટુ-લાઇન વોલ્ટેજ અને લાઇન કરંટનો ઉપયોગ કરીને, દેખીતી શક્તિ S = √3 × Vline × Iline છે. \nસક્રિય શક્તિ P = S × PF છે. \nઆ એક સંતુલિત sinusoidal AC સિસ્ટમ ધારે છે."},{"question":"સ્ટાર અને ડેલ્ટા વચ્ચે શું તફાવત છે?","answer":"સંતુલિત સ્ટાર (wye) કનેક્શન માટે, તબક્કો વોલ્ટેજ એ √3 વડે વિભાજિત રેખા વોલ્ટેજ છે અને તબક્કો વર્તમાન રેખા પ્રવાહની બરાબર છે. \nડેલ્ટામાં, તબક્કો વોલ્ટેજ લાઇન વોલ્ટેજની બરાબર છે અને તબક્કો પ્રવાહ એ રેખા પ્રવાહ છે જે √3 વડે વિભાજિત થાય છે. \nસમાન રેખા મૂલ્યોની કુલ શક્તિ સમાન છે."},{"question":"શું પાવર ફેક્ટર સક્રિય પાવરને અસર કરે છે?","answer":"હા. \nસક્રિય શક્તિ એ સ્પષ્ટ શક્તિ છે જે પાવર ફેક્ટર દ્વારા ગુણાકાર કરવામાં આવે છે. \nલોઅર પાવર ફેક્ટર એટલે સમાન લાઇન વોલ્ટેજ અને વર્તમાન માટે ઓછી સક્રિય શક્તિ; \nપ્રતિક્રિયાશીલ-શક્તિની તીવ્રતા S × √(1 − PF²) થી અંદાજવામાં આવે છે."},{"question":"શું હું આનો ઉપયોગ અસંતુલિત લોડ અથવા ઇલેક્ટ્રિકલ સેફ્ટી ડિઝાઇન માટે કરી શકું?","answer":"નંબર. સિંગલ ફેઝ અથવા બેલેન્સ્ડ થ્રી ફેઝ માટે આ એક આદર્શ અંદાજ છે. \nતે અસંતુલિત તબક્કાઓ, હાર્મોનિક્સ, વાયરિંગ, સાધનો રેટિંગ, રક્ષણ, આંચકો અથવા આગનું જોખમ અથવા સ્થાનિક ઇલેક્ટ્રિકલ કોડ્સનું વિશ્લેષણ કરતું નથી."}],"localizationStatus":"machine-accepted","localizationAcceptedBy":"site-owner","localizationAcceptedAt":"2026-10-09"}});
